window.NEN=[{"id": "lam-quen-de-toeic", "group": "Tổng quan", "title": "Làm quen đề TOEIC Listening & Reading", "level": 1, "mins": 8, "why": "Biết trước đề có mấy Part, mỗi Part bao nhiêu câu và bao nhiêu phút giúp bạn chia thời gian hợp lý, không hoảng khi vào phòng thi.", "sections": [{"h": "Tổng quan bài thi", "html": "<table><tr><th>Phần</th><th>Số câu</th><th>Thời gian</th><th>Điểm</th></tr><tr><td>Listening (Nghe)</td><td>100</td><td>khoảng 45 phút</td><td>5–495</td></tr><tr><td>Reading (Đọc)</td><td>100</td><td>75 phút</td><td>5–495</td></tr><tr><td><b>Tổng</b></td><td><b>200</b></td><td><b>khoảng 2 tiếng</b></td><td><b>10–990</b></td></tr></table><div class=\"note\">Câu sai <b>không bị trừ điểm</b>. Vì vậy đừng bỏ trống câu nào, không chắc thì vẫn chọn một đáp án.</div>"}, {"h": "Phần Nghe: Part 1–4", "html": "<table><tr><th>Part</th><th>Dạng bài</th><th>Số câu</th><th>Ghi chú</th></tr><tr><td>1</td><td>Tả tranh (Photographs)</td><td>6</td><td>4 đáp án, chọn câu tả đúng bức tranh</td></tr><tr><td>2</td><td>Hỏi – đáp (Question-Response)</td><td>25</td><td>Chỉ có <b>3 đáp án</b> A, B, C; không in chữ trong đề</td></tr><tr><td>3</td><td>Hội thoại (Conversations)</td><td>39</td><td>13 đoạn, mỗi đoạn 3 câu hỏi</td></tr><tr><td>4</td><td>Bài nói ngắn (Talks)</td><td>30</td><td>10 bài, mỗi bài 3 câu hỏi</td></tr></table><p>Đoạn nghe chỉ phát <b>một lần</b>, không được tua lại.</p>"}, {"h": "Phần Đọc: Part 5–7", "html": "<table><tr><th>Part</th><th>Dạng bài</th><th>Số câu</th><th>Thời gian gợi ý</th></tr><tr><td>5</td><td>Điền vào câu (Incomplete Sentences)</td><td>30</td><td>khoảng 15 phút</td></tr><tr><td>6</td><td>Điền vào đoạn văn (Text Completion)</td><td>16</td><td>khoảng 10 phút</td></tr><tr><td>7</td><td>Đọc hiểu (Reading Comprehension)</td><td>54</td><td>khoảng 50 phút</td></tr></table><p>Phần Đọc tự chia thời gian, nên dễ bị thiếu giờ ở Part 7 nếu làm Part 5–6 quá chậm.</p>"}, {"h": "Thang điểm 990 hiểu thế nào?", "html": "<ul><li>Điểm không phải số câu đúng nhân với 5. Điểm được quy đổi theo bảng riêng của từng đề.</li><li>Mỗi kỹ năng tối đa <b>495</b>, cộng lại tối đa <b>990</b>.</li><li>Người mới bắt đầu nên đặt mục tiêu từng bước, ví dụ 300 → 450 → 550.</li></ul>"}], "tips": ["Phần Đọc: làm Part 5 khoảng 30 giây mỗi câu để dành thời gian cho Part 7.", "Tô đáp án cho mọi câu trước khi hết giờ vì câu sai không bị trừ điểm.", "Lúc băng đọc hướng dẫn (Directions) của mỗi Part, hãy tranh thủ đọc trước câu hỏi."], "mistakes": ["Bỏ trống câu khó → nên đoán một đáp án, vì không bị trừ điểm.", "Nghĩ Part 2 có 4 đáp án như các Part khác → Part 2 chỉ có A, B, C.", "Dành quá nhiều thời gian cho một câu Part 5 → không chắc thì chọn tạm rồi đi tiếp."], "quiz": [{"q": "Bài thi TOEIC Listening & Reading có tổng cộng bao nhiêu câu?", "opts": ["200", "100", "150", "250"], "a": 0, "ex": "Nghe 100 câu + Đọc 100 câu = 200 câu."}, {"q": "Part nào chỉ có 3 đáp án (A, B, C)?", "opts": ["Part 1", "Part 3", "Part 2", "Part 5"], "a": 2, "ex": "Part 2 (Hỏi – đáp) chỉ có 3 đáp án. Các Part còn lại có 4 đáp án."}, {"q": "Phần Đọc (Reading) kéo dài bao lâu?", "opts": ["60 phút", "75 phút", "120 phút", "45 phút"], "a": 1, "ex": "Phần Đọc có 75 phút cho 100 câu. Phần Nghe khoảng 45 phút."}, {"q": "Điểm tối đa của riêng phần Nghe là bao nhiêu?", "opts": ["450", "500", "990", "495"], "a": 3, "ex": "Mỗi kỹ năng tối đa 495 điểm; hai kỹ năng cộng lại là 990."}, {"q": "Part 7 có bao nhiêu câu?", "opts": ["16", "30", "54", "39"], "a": 2, "ex": "Part 7 là phần đọc hiểu dài nhất với 54 câu. 30 là Part 5, 16 là Part 6, 39 là Part 3."}, {"q": "Part 1 là dạng bài gì?", "opts": ["Tả tranh", "Điền vào câu", "Hỏi – đáp", "Đọc hiểu đoạn văn"], "a": 0, "ex": "Part 1 (Photographs): nghe 4 câu và chọn câu tả đúng bức tranh."}, {"q": "Part 6 có bao nhiêu câu?", "opts": ["25", "6", "30", "16"], "a": 3, "ex": "Part 6 có 4 đoạn văn, mỗi đoạn 4 chỗ trống, tổng cộng 16 câu."}, {"q": "Câu nào ĐÚNG về bài thi TOEIC Listening & Reading?", "opts": ["Câu sai bị trừ điểm", "Câu sai không bị trừ điểm, nên không bỏ trống câu nào", "Part 3 có 25 câu", "Mỗi đoạn nghe được phát hai lần"], "a": 1, "ex": "TOEIC không trừ điểm câu sai. Đoạn nghe chỉ phát một lần, và Part 3 có 39 câu (25 câu là Part 2)."}]}, {"id": "cau-truc-cau-co-ban", "group": "Ngữ pháp", "title": "Cấu trúc câu cơ bản (S + V + O)", "level": 1, "mins": 8, "why": "Ở Part 5 và Part 6, rất nhiều câu hỏi chỉ cần biết câu đang thiếu thành phần nào (thiếu động từ, thiếu tân ngữ...). Nắm khung câu giúp bạn loại nhanh các đáp án sai.", "sections": [{"h": "Khung câu cơ bản", "html": "<p>Câu tiếng Anh cơ bản gồm: <b>Chủ ngữ (S) + Động từ (V) + Tân ngữ (O)</b>.</p><table><tr><th>Thành phần</th><th>Là gì</th><th>Ví dụ</th></tr><tr><td>S – Chủ ngữ</td><td>Người/vật thực hiện hành động</td><td><span class=\"en\">The manager</span></td></tr><tr><td>V – Động từ</td><td>Hành động/trạng thái</td><td><span class=\"en\">signed</span></td></tr><tr><td>O – Tân ngữ</td><td>Người/vật nhận hành động</td><td><span class=\"en\">the contract</span></td></tr></table><div class=\"ex\"><span class=\"en\">The manager signed the contract.</span> <span class=\"vi\">Người quản lý đã ký hợp đồng.</span><br><span class=\"en\">Our team sells software.</span> <span class=\"vi\">Nhóm chúng tôi bán phần mềm.</span></div>"}, {"h": "Quy tắc vàng: mỗi mệnh đề cần 1 động từ chia", "html": "<p>Mỗi mệnh đề (một cụm có chủ ngữ riêng) phải có <b>đúng 1 động từ chính được chia thì</b>. Các dạng <b>V-ing, to V, danh từ</b> không thể đứng một mình làm động từ chính.</p><table><tr><th>Sai</th><th>Đúng</th></tr><tr><td><span class=\"en\">The company expanding.</span></td><td><span class=\"en\">The company <b>is expanding</b>.</span></td></tr><tr><td><span class=\"en\">She to send the file.</span></td><td><span class=\"en\">She <b>sent</b> the file.</span></td></tr></table><div class=\"note\">Khi thấy câu chưa có động từ chính, hãy chọn đáp án là động từ đã chia (có thì, có s/es, có will...).</div>"}, {"h": "Động từ nối (linking verbs)", "html": "<p>Một số động từ không cần tân ngữ mà đi với <b>tính từ</b>: <b>be, become, seem, look, remain, feel</b>.</p><div class=\"ex\"><span class=\"en\">The new office seems spacious.</span> <span class=\"vi\">Văn phòng mới có vẻ rộng rãi.</span><br><span class=\"en\">Prices remain stable.</span> <span class=\"vi\">Giá cả vẫn ổn định.</span></div>"}], "tips": ["Đọc câu, tìm chủ ngữ trước, rồi hỏi: câu đã có động từ chính chưa?", "Nếu câu có who/which/that, mệnh đề phía sau cũng cần động từ riêng."], "mistakes": ["Dùng V-ing làm động từ chính (The staff working hard) – phải có be: The staff are working hard.", "Bỏ quên s/es khi chủ ngữ số ít (She send) – sửa: She sends.", "Dùng hai động từ chia trong một mệnh đề (He is work here) – sửa: He works here."], "quiz": [{"q": "The manager ____ the new schedule yesterday.", "opts": ["approval", "approved", "approving", "to approve"], "a": 1, "ex": "Câu chưa có động từ chính, lại có 'yesterday' nên cần động từ quá khứ: approved. 'approval' là danh từ, 'approving' và 'to approve' không làm động từ chính được."}, {"q": "All employees ____ the safety training next week.", "opts": ["attending", "to attend", "will attend", "attendance"], "a": 2, "ex": "Câu cần động từ chính; 'next week' chỉ tương lai nên chọn 'will attend'."}, {"q": "Ms. Tran ____ a report to the board every month.", "opts": ["submits", "submitting", "to submit", "submission"], "a": 0, "ex": "Chủ ngữ số ít, thói quen 'every month' → động từ hiện tại đơn có s: submits."}, {"q": "The new meeting room ____ very comfortable.", "opts": ["seeming", "seems", "to seem", "seem"], "a": 1, "ex": "Cần động từ chính chia theo chủ ngữ số ít 'room' → seems. 'seem' dùng cho chủ ngữ số nhiều."}, {"q": "Customers who ____ before Friday will receive a discount.", "opts": ["register", "registration", "registering", "to register"], "a": 0, "ex": "Sau 'who' là một mệnh đề mới nên cần động từ chia: 'who register'. 'Customers' số nhiều nên không thêm s."}, {"q": "Câu nào đúng ngữ pháp?", "opts": ["The company expanding its branches.", "The company is expanding its branches.", "The company to expand its branches.", "The company expansion its branches."], "a": 1, "ex": "Chỉ câu B có động từ chính được chia (is expanding). Các câu còn lại thiếu động từ chính."}, {"q": "The director ____ the proposal before the meeting starts.", "opts": ["reviewing", "to review", "review", "will review"], "a": 3, "ex": "Câu cần động từ chính. 'review' sai vì chủ ngữ số ít; 'reviewing', 'to review' không làm động từ chính. Chọn 'will review'."}]}, {"id": "tu-loai-vi-tri", "group": "Ngữ pháp", "title": "Từ loại và vị trí trong câu", "level": 1, "mins": 10, "why": "Câu hỏi từ loại (4 đáp án cùng gốc từ: inform, information, informative, informatively) chiếm khoảng 1/4 Part 5. Chỉ cần nhìn vị trí chỗ trống là chọn được mà không cần hiểu hết câu.", "sections": [{"h": "Nhận biết từ loại qua đuôi", "html": "<table><tr><th>Từ loại</th><th>Đuôi thường gặp</th><th>Ví dụ</th></tr><tr><td>Danh từ (N)</td><td>-tion, -sion, -ment, -ness, -ity, -ance, -ence, -er/-or</td><td><span class=\"en\">information, payment, kindness, ability</span></td></tr><tr><td>Động từ (V)</td><td>-ize, -ify, -en, -ate</td><td><span class=\"en\">organize, simplify, widen, create</span></td></tr><tr><td>Tính từ (Adj)</td><td>-ive, -ful, -ous, -able/-ible, -al, -ic, -less</td><td><span class=\"en\">effective, useful, famous, available</span></td></tr><tr><td>Trạng từ (Adv)</td><td>Tính từ + -ly</td><td><span class=\"en\">quickly, carefully, effectively</span></td></tr></table><div class=\"note\">Cẩn thận: một số từ đuôi -ly là tính từ: <span class=\"en\">friendly, costly, timely</span>.</div>"}, {"h": "Vị trí của danh từ", "html": "<ul><li>Sau <b>a/an/the</b>: <span class=\"en\">the <b>decision</b></span></li><li>Sau <b>tính từ sở hữu</b> (my, your, his, their, its...): <span class=\"en\">our <b>cooperation</b></span></li><li>Sau <b>tính từ</b>: <span class=\"en\">a quick <b>response</b></span></li><li>Sau <b>giới từ</b>: <span class=\"en\">for your <b>information</b></span></li></ul>"}, {"h": "Vị trí của tính từ và trạng từ", "html": "<table><tr><th>Từ loại</th><th>Vị trí</th><th>Ví dụ</th></tr><tr><td>Tính từ</td><td>Trước danh từ</td><td><span class=\"en\">a <b>competitive</b> price</span> <span class=\"vi\">giá cạnh tranh</span></td></tr><tr><td>Tính từ</td><td>Sau be/become/seem</td><td><span class=\"en\">The plan is <b>successful</b>.</span></td></tr><tr><td>Trạng từ</td><td>Bổ nghĩa động từ</td><td><span class=\"en\">She replied <b>quickly</b>.</span></td></tr><tr><td>Trạng từ</td><td>Giữa be và V3/V-ing</td><td><span class=\"en\">was <b>carefully</b> checked</span></td></tr><tr><td>Trạng từ</td><td>Trước tính từ</td><td><span class=\"en\"><b>extremely</b> busy</span></td></tr></table>"}], "tips": ["Nhìn từ ngay trước và ngay sau chỗ trống trước khi đọc cả câu.", "the/a/my + ____ + giới từ/động từ → gần như chắc chắn là danh từ.", "Câu đã đủ thành phần (S + V + O) mà còn chỗ trống → thường là trạng từ."], "mistakes": ["Chọn tính từ để bổ nghĩa cho động từ (respond quick) – sửa: respond quickly.", "Thấy đuôi -ly là chọn trạng từ, quên friendly/costly là tính từ.", "Dùng động từ sau the (the construct) – sửa: the construction."], "quiz": [{"q": "Please read the ____ carefully before signing the form.", "opts": ["instruct", "instructions", "instructive", "instructively"], "a": 1, "ex": "Sau 'the' cần danh từ → instructions (hướng dẫn)."}, {"q": "The company offers ____ prices to its loyal customers.", "opts": ["competitive", "compete", "competition", "competitively"], "a": 0, "ex": "Trước danh từ 'prices' cần tính từ → competitive (cạnh tranh)."}, {"q": "Mr. Lee responded ____ to the client's complaint.", "opts": ["quick", "quickly", "quickness", "quicken"], "a": 1, "ex": "Bổ nghĩa cho động từ 'responded' cần trạng từ → quickly."}, {"q": "The new software is very ____ for small businesses.", "opts": ["use", "usefully", "useful", "usefulness"], "a": 2, "ex": "Sau 'is very' cần tính từ → useful (hữu ích)."}, {"q": "We appreciate your ____ in this matter.", "opts": ["cooperate", "cooperative", "cooperatively", "cooperation"], "a": 3, "ex": "Sau tính từ sở hữu 'your' cần danh từ → cooperation (sự hợp tác)."}, {"q": "The report was ____ prepared by the finance team.", "opts": ["careful", "care", "carefulness", "carefully"], "a": 3, "ex": "Giữa 'was' và V3 'prepared' cần trạng từ → carefully."}, {"q": "Đuôi nào thường là dấu hiệu của TÍNH TỪ?", "opts": ["-ment", "-ness", "-ous", "-tion"], "a": 2, "ex": "-ous là đuôi tính từ (famous, various). -ment, -ness, -tion là đuôi danh từ."}, {"q": "The ____ of the new factory took two years.", "opts": ["construct", "construction", "constructive", "constructively"], "a": 1, "ex": "Sau 'the' và trước 'of' cần danh từ → construction (việc xây dựng)."}]}, {"id": "thi-hien-tai", "group": "Ngữ pháp", "title": "Thì hiện tại: đơn, tiếp diễn, hoàn thành", "level": 1, "mins": 10, "why": "Part 5 thường cho 4 đáp án là cùng một động từ ở các thì khác nhau. Nhìn dấu hiệu thời gian trong câu (every day, currently, since...) là chọn được ngay.", "sections": [{"h": "Công thức", "html": "<table><tr><th>Thì</th><th>Công thức</th><th>Dùng khi</th></tr><tr><td>Hiện tại đơn</td><td>S + V(s/es)</td><td>Thói quen, sự thật, lịch trình cố định</td></tr><tr><td>Hiện tại tiếp diễn</td><td>S + am/is/are + V-ing</td><td>Đang xảy ra lúc nói / giai đoạn hiện tại</td></tr><tr><td>Hiện tại hoàn thành</td><td>S + have/has + V3</td><td>Bắt đầu trong quá khứ, kéo dài/ảnh hưởng đến nay</td></tr></table>"}, {"h": "Dấu hiệu nhận biết", "html": "<table><tr><th>Thì</th><th>Dấu hiệu</th></tr><tr><td>Hiện tại đơn</td><td><span class=\"en\">every day/week, usually, often, always, regularly, generally</span></td></tr><tr><td>Hiện tại tiếp diễn</td><td><span class=\"en\">now, right now, currently, at the moment, this week</span></td></tr><tr><td>Hiện tại hoàn thành</td><td><span class=\"en\">since + mốc, for + khoảng, already, yet, recently, so far, over the past + thời gian</span></td></tr></table>"}, {"h": "Ví dụ", "html": "<div class=\"ex\"><span class=\"en\">The shop usually opens at 8 A.M.</span> <span class=\"vi\">Cửa hàng thường mở lúc 8 giờ sáng.</span><br><span class=\"en\">Our team is currently testing the app.</span> <span class=\"vi\">Nhóm chúng tôi hiện đang thử nghiệm ứng dụng.</span><br><span class=\"en\">Ms. Hoa has worked here since 2018.</span> <span class=\"vi\">Cô Hoa đã làm việc ở đây từ năm 2018.</span><br><span class=\"en\">We have not received the invoice yet.</span> <span class=\"vi\">Chúng tôi vẫn chưa nhận được hóa đơn.</span></div>"}], "tips": ["Gạch chân trạng từ thời gian trong câu trước khi nhìn đáp án.", "Thấy since / for / over the past → nghĩ ngay đến have/has + V3."], "mistakes": ["Quên thêm s/es với chủ ngữ số ít ở hiện tại đơn (He work) – sửa: He works.", "Dùng quá khứ đơn với since (I worked here since 2020) – sửa: I have worked.", "Viết 'is work' – tiếp diễn phải là 'is working'."], "quiz": [{"q": "Ms. Kim usually ____ the bus to work.", "opts": ["take", "takes", "is taking", "has taken"], "a": 1, "ex": "'usually' là dấu hiệu hiện tại đơn, chủ ngữ số ít → takes."}, {"q": "The marketing team ____ on a new campaign at the moment.", "opts": ["works", "work", "is working", "has worked"], "a": 2, "ex": "'at the moment' → hiện tại tiếp diễn: is working."}, {"q": "Mr. Park ____ at this company since 2019.", "opts": ["has worked", "works", "is working", "worked"], "a": 0, "ex": "'since 2019' → hiện tại hoàn thành: has worked."}, {"q": "We ____ received your payment yet.", "opts": ["did not", "have not", "are not", "do not"], "a": 1, "ex": "'yet' + V3 'received' → hiện tại hoàn thành phủ định: have not received."}, {"q": "Sales ____ steadily over the past three months.", "opts": ["increase", "increases", "is increasing", "have increased"], "a": 3, "ex": "'over the past three months' → hiện tại hoàn thành; 'Sales' số nhiều → have increased."}, {"q": "The train to Hanoi ____ at 7 A.M. every day.", "opts": ["leave", "leaves", "is leaving", "has left"], "a": 1, "ex": "Lịch trình cố định 'every day' → hiện tại đơn, chủ ngữ số ít → leaves."}, {"q": "Dấu hiệu nào thường đi với thì hiện tại hoàn thành?", "opts": ["every day", "at the moment", "since 2020", "usually"], "a": 2, "ex": "'since + mốc thời gian' là dấu hiệu của hiện tại hoàn thành. 'every day', 'usually' → hiện tại đơn; 'at the moment' → tiếp diễn."}]}, {"id": "thi-qua-khu-tuong-lai", "group": "Ngữ pháp", "title": "Thì quá khứ và tương lai", "level": 1, "mins": 10, "why": "Câu hỏi về thì ở Part 5/6 rất hay dùng 'last year', 'ago', 'next week'. Đặc biệt TOEIC thích bẫy: sau when/if/before/as soon as phải dùng hiện tại đơn dù nói về tương lai.", "sections": [{"h": "Quá khứ đơn", "html": "<p><b>S + V2/V-ed</b> – hành động đã xong trong quá khứ.</p><p>Dấu hiệu: <span class=\"en\">yesterday, last week/year, ago, in 2020</span></p><div class=\"ex\"><span class=\"en\">The company opened a new branch last year.</span> <span class=\"vi\">Công ty đã mở chi nhánh mới năm ngoái.</span><br><span class=\"en\">Ms. Linh finished the report two days ago.</span> <span class=\"vi\">Cô Linh đã xong báo cáo hai ngày trước.</span></div>"}, {"h": "Tương lai: will và be going to", "html": "<table><tr><th>Cấu trúc</th><th>Dùng khi</th><th>Ví dụ</th></tr><tr><td>will + V</td><td>Dự đoán, quyết định, lời hứa</td><td><span class=\"en\">We will send the invoice tomorrow.</span></td></tr><tr><td>be going to + V</td><td>Kế hoạch đã định / có dấu hiệu rõ</td><td><span class=\"en\">They are going to hire two new staff.</span></td></tr></table><p>Dấu hiệu: <span class=\"en\">tomorrow, next week/month, soon, in the future</span></p>"}, {"h": "Bẫy: hiện tại đơn sau when/if/before/as soon as", "html": "<p>Trong mệnh đề bắt đầu bằng <b>when, if, before, after, as soon as, until, once</b>, ta dùng <b>hiện tại đơn</b> để nói về tương lai (KHÔNG dùng will).</p><table><tr><th>Sai</th><th>Đúng</th></tr><tr><td><span class=\"en\">Call me when he will arrive.</span></td><td><span class=\"en\">Call me when he <b>arrives</b>.</span></td></tr><tr><td><span class=\"en\">If it will rain, we will stay inside.</span></td><td><span class=\"en\">If it <b>rains</b>, we will stay inside.</span></td></tr></table><div class=\"note\">Mệnh đề chính vẫn dùng will bình thường: <span class=\"en\">We will start <b>as soon as</b> everyone arrives.</span></div>"}], "tips": ["Thấy 'ago' hoặc 'last' → chọn V2/V-ed.", "Thấy when/if/before/as soon as + chỗ trống → chọn hiện tại đơn, loại will."], "mistakes": ["Dùng will sau when/if (when the order will arrive) – sửa: when the order arrives.", "Quên chia V2 với động từ bất quy tắc (buyed) – sửa: bought.", "Dùng 'will' đi với V-ing hoặc to V (will to send) – sửa: will send."], "quiz": [{"q": "The company ____ a new branch in Da Nang last year.", "opts": ["opens", "opened", "will open", "has opened"], "a": 1, "ex": "'last year' → quá khứ đơn: opened."}, {"q": "Please call me as soon as the shipment ____.", "opts": ["arrives", "will arrive", "arrived", "arriving"], "a": 0, "ex": "Sau 'as soon as' nói về tương lai ta dùng hiện tại đơn → arrives (không dùng will)."}, {"q": "Mr. Hoang ____ the conference in Singapore next week.", "opts": ["attended", "will attend", "has attended", "attending"], "a": 1, "ex": "'next week' → tương lai: will attend. 'attending' thiếu động từ be."}, {"q": "Before you ____ the office, please turn off the lights.", "opts": ["will leave", "left", "leaving", "leave"], "a": 3, "ex": "Sau 'before' nói về tương lai/thói quen dùng hiện tại đơn → leave."}, {"q": "Ms. Linh ____ the sales report two days ago.", "opts": ["finish", "will finish", "finished", "has finished"], "a": 2, "ex": "'two days ago' → quá khứ đơn: finished. Hiện tại hoàn thành không đi với 'ago'."}, {"q": "According to the new plan, the company ____ hire ten more workers next month.", "opts": ["is going to", "was", "has", "did"], "a": 0, "ex": "Kế hoạch đã định cho 'next month' → is going to + V (is going to hire)."}, {"q": "If the client ____ the contract tomorrow, we will start the project on Monday.", "opts": ["will sign", "signs", "signed", "signing"], "a": 1, "ex": "Sau 'if' nói về tương lai dùng hiện tại đơn → signs. Mệnh đề chính mới dùng will."}]}, {"id": "hoa-hop-chu-ngu-dong-tu", "group": "Ngữ pháp", "title": "Hòa hợp chủ ngữ – động từ", "level": 2, "mins": 10, "why": "Part 5 hay cho đáp án is/are, has/have, offer/offers và gài một cụm dài giữa chủ ngữ và động từ để đánh lừa. Biết tìm chủ ngữ thật là ăn điểm.", "sections": [{"h": "Quy tắc cơ bản", "html": "<table><tr><th>Chủ ngữ</th><th>Động từ</th><th>Ví dụ</th></tr><tr><td>Số ít (he, she, it, danh từ số ít)</td><td>is / has / V-s</td><td><span class=\"en\">The manager <b>has</b> a meeting.</span></td></tr><tr><td>Số nhiều (they, we, danh từ số nhiều)</td><td>are / have / V</td><td><span class=\"en\">The managers <b>have</b> a meeting.</span></td></tr></table>"}, {"h": "Các trường hợp đặc biệt", "html": "<table><tr><th>Cấu trúc</th><th>Động từ</th><th>Ví dụ</th></tr><tr><td>each / every + N số ít</td><td>Số ít</td><td><span class=\"en\">Every room <b>has</b> a TV.</span></td></tr><tr><td>The number of + N số nhiều</td><td>Số ít</td><td><span class=\"en\">The number of orders <b>has</b> doubled.</span> <span class=\"vi\">Số lượng đơn hàng...</span></td></tr><tr><td>A number of + N số nhiều</td><td>Số nhiều</td><td><span class=\"en\">A number of staff <b>have</b> left.</span> <span class=\"vi\">Một số nhân viên...</span></td></tr><tr><td>Danh từ không đếm được (information, equipment)</td><td>Số ít</td><td><span class=\"en\">The equipment <b>is</b> new.</span></td></tr></table>"}, {"h": "Cụm chen giữa chủ ngữ và động từ", "html": "<p>Bỏ qua các cụm giới từ (<b>of..., in..., on...</b>) và cụm <b>together with / along with / as well as</b>. Động từ chia theo danh từ <b>đứng trước</b> các cụm này.</p><div class=\"ex\"><span class=\"en\">The list <i>of new products</i> is on the website.</span> <span class=\"vi\">Danh sách (số ít) → is</span><br><span class=\"en\">Mr. Tan, <i>together with his assistants</i>, attends the fair.</span> <span class=\"vi\">Chủ ngữ là Mr. Tan → attends</span></div>"}], "tips": ["Gạch bỏ cụm 'of + ...' để tìm chủ ngữ thật.", "Nhớ: THE number → số ít; A number → số nhiều."], "mistakes": ["Chia động từ theo danh từ gần nhất (The list of products are) – sửa: is.", "Dùng số nhiều sau each/every (Each employee have) – sửa: has.", "Thêm s vào information/equipment – chúng không đếm được."], "quiz": [{"q": "Each employee ____ a parking card.", "opts": ["receive", "receives", "are receiving", "have received"], "a": 1, "ex": "'Each + danh từ số ít' → động từ số ít: receives."}, {"q": "The number of applicants ____ increased this year.", "opts": ["has", "have", "are", "were"], "a": 0, "ex": "'The number of' (số lượng) → động từ số ít: has increased."}, {"q": "A number of customers ____ complained about the delay.", "opts": ["has", "have", "is", "was"], "a": 1, "ex": "'A number of' (một số) + danh từ số nhiều → động từ số nhiều: have complained."}, {"q": "The list of new products ____ on our website.", "opts": ["are", "were", "is", "have"], "a": 2, "ex": "Chủ ngữ thật là 'The list' (số ít), bỏ qua 'of new products' → is."}, {"q": "The documents on the manager's desk ____ ready to sign.", "opts": ["is", "was", "has", "are"], "a": 3, "ex": "Chủ ngữ là 'The documents' (số nhiều), 'on the manager's desk' chỉ là cụm chen → are."}, {"q": "Every room in the hotel ____ free Wi-Fi.", "opts": ["offer", "offers", "are offering", "have offered"], "a": 1, "ex": "'Every room' là số ít → offers."}, {"q": "Mr. Tan, together with his assistants, ____ the trade fair every year.", "opts": ["attends", "attend", "are attending", "have attended"], "a": 0, "ex": "Chủ ngữ là 'Mr. Tan' (số ít); cụm 'together with...' không tính. 'every year' → hiện tại đơn: attends."}]}, {"id": "cau-bi-dong", "group": "Ngữ pháp", "title": "Câu bị động (Passive voice)", "level": 2, "mins": 10, "why": "Câu bị động xuất hiện liên tục trong email, thông báo ở Part 5, 6, 7 (The meeting has been postponed...). Part 5 thường hỏi chọn chủ động hay bị động.", "sections": [{"h": "Công thức", "html": "<p><b>S + be + V3 (+ by + người làm)</b></p><table><tr><th>Thì</th><th>Bị động</th><th>Ví dụ</th></tr><tr><td>Hiện tại đơn</td><td>am/is/are + V3</td><td><span class=\"en\">Orders are processed daily.</span></td></tr><tr><td>Quá khứ đơn</td><td>was/were + V3</td><td><span class=\"en\">The CEO was chosen last week.</span></td></tr><tr><td>Hiện tại hoàn thành</td><td>have/has been + V3</td><td><span class=\"en\">The meeting has been postponed.</span></td></tr><tr><td>Tương lai</td><td>will be + V3</td><td><span class=\"en\">The office will be renovated.</span></td></tr><tr><td>Tiếp diễn</td><td>am/is/are being + V3</td><td><span class=\"en\">The products are being tested.</span></td></tr></table>"}, {"h": "Khi nào chọn bị động?", "html": "<ul><li>Chủ ngữ là <b>vật</b> không tự làm được hành động: <span class=\"en\">The report <b>was written</b>.</span> <span class=\"vi\">Báo cáo được viết.</span></li><li>Sau chỗ trống <b>không có tân ngữ</b> mà có <b>by</b>: <span class=\"en\">was designed <b>by</b> Ms. Ha</span></li></ul><div class=\"note\">Mẹo: động từ cần tân ngữ (send, review, approve) mà phía sau không có tân ngữ → thường là bị động.</div>"}, {"h": "So sánh chủ động – bị động", "html": "<div class=\"ex\"><span class=\"en\">Ms. Ha wrote the report.</span> <span class=\"vi\">Chủ động: Cô Hà viết báo cáo.</span><br><span class=\"en\">The report was written by Ms. Ha.</span> <span class=\"vi\">Bị động: Báo cáo được viết bởi cô Hà.</span></div>"}], "tips": ["Hỏi: chủ ngữ tự làm hay bị/được làm? Bị/được → be + V3.", "Có tân ngữ ngay sau chỗ trống → thường là chủ động."], "mistakes": ["Quên 'be' (The meeting postponed until Monday) – sửa: was postponed.", "Dùng V2 thay vì V3 trong bị động (was wrote) – sửa: was written.", "Dùng bị động khi có tân ngữ phía sau (was written the report)."], "quiz": [{"q": "The meeting ____ until next Tuesday.", "opts": ["has postponed", "has been postponed", "postponing", "postpone"], "a": 1, "ex": "Cuộc họp không tự hoãn, mà 'bị hoãn' → bị động: has been postponed."}, {"q": "All orders ____ within 24 hours.", "opts": ["process", "processing", "are processed", "have processed"], "a": 2, "ex": "Đơn hàng 'được xử lý' và không có tân ngữ phía sau → bị động: are processed."}, {"q": "The new manager ____ by the board last week.", "opts": ["chose", "has chosen", "choosing", "was chosen"], "a": 3, "ex": "Có 'by the board' và 'last week' → bị động quá khứ: was chosen."}, {"q": "The sales report was written ____ Ms. Ha.", "opts": ["by", "with", "from", "of"], "a": 0, "ex": "Trong câu bị động, người thực hiện hành động đứng sau 'by'."}, {"q": "Ms. Ha ____ the sales report for the meeting.", "opts": ["wrote", "was written", "writing", "been written"], "a": 0, "ex": "Chủ ngữ 'Ms. Ha' tự viết, và có tân ngữ 'the sales report' → chủ động: wrote."}, {"q": "The main office will ____ next month.", "opts": ["renovate", "be renovated", "renovating", "renovated"], "a": 1, "ex": "Văn phòng 'được sửa chữa', không có tân ngữ → will be + V3: be renovated."}, {"q": "The new products ____ in the lab right now.", "opts": ["are testing", "test", "are being tested", "tested"], "a": 2, "ex": "Sản phẩm 'đang được kiểm tra' ('right now') → bị động tiếp diễn: are being tested."}]}, {"id": "dai-tu", "group": "Ngữ pháp", "title": "Đại từ: nhân xưng, tân ngữ, sở hữu, phản thân", "level": 1, "mins": 8, "why": "Part 5 gần như đề nào cũng có 1–2 câu cho 4 đáp án như they / them / their / themselves. Chỉ cần nhìn vị trí là chọn được.", "sections": [{"h": "Bảng đại từ", "html": "<table><tr><th>Chủ ngữ</th><th>Tân ngữ</th><th>Tính từ sở hữu</th><th>Đại từ sở hữu</th><th>Phản thân</th></tr><tr><td>I</td><td>me</td><td>my</td><td>mine</td><td>myself</td></tr><tr><td>you</td><td>you</td><td>your</td><td>yours</td><td>yourself</td></tr><tr><td>he</td><td>him</td><td>his</td><td>his</td><td>himself</td></tr><tr><td>she</td><td>her</td><td>her</td><td>hers</td><td>herself</td></tr><tr><td>it</td><td>it</td><td>its</td><td>–</td><td>itself</td></tr><tr><td>we</td><td>us</td><td>our</td><td>ours</td><td>ourselves</td></tr><tr><td>they</td><td>them</td><td>their</td><td>theirs</td><td>themselves</td></tr></table>"}, {"h": "Vị trí dùng", "html": "<table><tr><th>Loại</th><th>Vị trí</th><th>Ví dụ</th></tr><tr><td>Chủ ngữ</td><td>Đầu câu, trước động từ</td><td><span class=\"en\"><b>She</b> works in sales.</span></td></tr><tr><td>Tân ngữ</td><td>Sau động từ / giới từ</td><td><span class=\"en\">Please call <b>me</b>.</span></td></tr><tr><td>Tính từ sở hữu</td><td>Trước danh từ</td><td><span class=\"en\"><b>their</b> office</span></td></tr><tr><td>Đại từ sở hữu</td><td>Đứng một mình, thay cho 'tính từ sở hữu + N'</td><td><span class=\"en\">This pen is <b>mine</b>.</span></td></tr><tr><td>Phản thân</td><td>Chủ ngữ tự làm cho mình / by + oneself (tự mình)</td><td><span class=\"en\">She did it <b>by herself</b>.</span></td></tr></table>"}, {"h": "Chú ý its và it's", "html": "<p><b>its</b> = của nó (tính từ sở hữu). <b>it's</b> = it is.</p><div class=\"ex\"><span class=\"en\">The company updated its website.</span> <span class=\"vi\">Công ty đã cập nhật trang web của mình.</span></div>"}], "tips": ["Trước danh từ → tính từ sở hữu (my, their...).", "Sau 'by' với nghĩa 'tự mình' → đại từ phản thân."], "mistakes": ["Dùng 'me' làm chủ ngữ (Mr. Nam and me will lead) – sửa: Mr. Nam and I.", "Nhầm its với it's.", "Dùng 'mine/yours' trước danh từ (mine car) – sửa: my car."], "quiz": [{"q": "Please send ____ the updated file by Friday.", "opts": ["I", "me", "my", "mine"], "a": 1, "ex": "Sau động từ 'send' cần tân ngữ → me."}, {"q": "Ms. Lan completed the whole project by ____.", "opts": ["she", "her", "hers", "herself"], "a": 3, "ex": "'by + đại từ phản thân' = tự mình làm → by herself."}, {"q": "The clients were happy with ____ new office.", "opts": ["they", "them", "their", "theirs"], "a": 2, "ex": "Trước danh từ 'new office' cần tính từ sở hữu → their."}, {"q": "This laptop is not mine. I think it is ____.", "opts": ["your", "yours", "you", "yourself"], "a": 1, "ex": "Đứng một mình cuối câu, thay cho 'your laptop' → đại từ sở hữu yours."}, {"q": "Mr. Nam and ____ will lead the training session.", "opts": ["I", "me", "my", "myself"], "a": 0, "ex": "Vị trí chủ ngữ (trước 'will lead') → đại từ chủ ngữ I."}, {"q": "The company updated ____ website last month.", "opts": ["it", "its", "it's", "itself"], "a": 1, "ex": "Trước danh từ 'website' cần tính từ sở hữu → its. 'it's' = it is."}, {"q": "Employees should keep ____ passwords private.", "opts": ["their", "they", "them", "themselves"], "a": 0, "ex": "Trước danh từ 'passwords' cần tính từ sở hữu → their."}]}, {"id": "gioi-tu-thoi-gian-noi-chon", "group": "Ngữ pháp", "title": "Giới từ thời gian và nơi chốn", "level": 1, "mins": 10, "why": "Giới từ là dạng câu hỏi rất phổ biến ở Part 5 (by Friday, within 3 days, since 2020). Nghe Part 1–2 cũng cần hiểu in/on/at để nắm vị trí.", "sections": [{"h": "in / on / at", "html": "<table><tr><th>Giới từ</th><th>Thời gian</th><th>Nơi chốn</th></tr><tr><td>in</td><td>tháng, năm, mùa, buổi: <span class=\"en\">in May, in 2025, in the morning</span></td><td>thành phố, quốc gia, không gian kín: <span class=\"en\">in Hanoi, in the room</span></td></tr><tr><td>on</td><td>thứ, ngày cụ thể: <span class=\"en\">on Monday, on May 15</span></td><td>bề mặt, tầng: <span class=\"en\">on the desk, on the 3rd floor</span></td></tr><tr><td>at</td><td>giờ: <span class=\"en\">at 9 A.M., at noon</span></td><td>địa điểm cụ thể: <span class=\"en\">at the airport, at the front desk</span></td></tr></table>"}, {"h": "by và until", "html": "<table><tr><th>Giới từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td>by</td><td>trước hoặc đúng lúc (hạn chót), hành động xảy ra 1 lần</td><td><span class=\"en\">Submit the form <b>by</b> Friday.</span> <span class=\"vi\">Nộp chậm nhất thứ Sáu.</span></td></tr><tr><td>until</td><td>kéo dài liên tục đến lúc</td><td><span class=\"en\">The office is closed <b>until</b> Monday.</span> <span class=\"vi\">Đóng cửa cho đến thứ Hai.</span></td></tr></table>"}, {"h": "for / since / during / within", "html": "<table><tr><th>Giới từ</th><th>Đi với</th><th>Ví dụ</th></tr><tr><td>for</td><td>khoảng thời gian</td><td><span class=\"en\">for ten years</span></td></tr><tr><td>since</td><td>mốc thời gian (thường với hiện tại hoàn thành)</td><td><span class=\"en\">since 2019</span></td></tr><tr><td>during</td><td>trong suốt + danh từ sự kiện</td><td><span class=\"en\">during the meeting</span></td></tr><tr><td>within</td><td>trong vòng (không quá)</td><td><span class=\"en\">within seven days</span></td></tr></table>"}], "tips": ["Động từ một lần (submit, finish, send) + hạn chót → by.", "Động từ kéo dài (stay, wait, be closed) → until."], "mistakes": ["Dùng 'in' với thứ/ngày (in Monday) – sửa: on Monday.", "Nhầm for/since: since ten years – sửa: for ten years.", "Dùng during + mệnh đề (during he was talking) – sửa: while he was talking."], "quiz": [{"q": "The annual conference will be held ____ May 15.", "opts": ["in", "on", "at", "for"], "a": 1, "ex": "Ngày cụ thể (May 15) dùng 'on'."}, {"q": "The store opens ____ 9 A.M. every day.", "opts": ["in", "on", "at", "since"], "a": 2, "ex": "Giờ cụ thể dùng 'at'."}, {"q": "Please submit the application form ____ Friday.", "opts": ["by", "until", "since", "during"], "a": 0, "ex": "'submit' là hành động một lần, cần hạn chót → by (chậm nhất là thứ Sáu)."}, {"q": "The office will be closed ____ next Monday.", "opts": ["since", "until", "during", "at"], "a": 1, "ex": "Trạng thái đóng cửa kéo dài đến thứ Hai → until."}, {"q": "Mr. Vu has worked here ____ ten years.", "opts": ["since", "during", "for", "within"], "a": 2, "ex": "'ten years' là khoảng thời gian, đi với hiện tại hoàn thành → for."}, {"q": "No phones are allowed ____ the meeting.", "opts": ["during", "by", "since", "while"], "a": 0, "ex": "Trước danh từ sự kiện 'the meeting' → during. 'while' là liên từ, phải đi với mệnh đề."}, {"q": "You will receive a refund ____ seven business days.", "opts": ["since", "at", "until", "within"], "a": 3, "ex": "'within' = trong vòng (không quá) 7 ngày làm việc."}, {"q": "Our headquarters is located ____ Hanoi.", "opts": ["in", "on", "at", "for"], "a": 0, "ex": "Thành phố dùng 'in'."}]}, {"id": "lien-tu-gioi-tu-de-nham", "group": "Ngữ pháp", "title": "Liên từ và giới từ dễ nhầm", "level": 2, "mins": 10, "why": "Part 5 rất thích cho although / despite / because / because of trong cùng một câu. Điểm mấu chốt: phía sau là mệnh đề hay danh từ. Part 6 cũng hỏi từ nối giữa các câu.", "sections": [{"h": "Liên từ + mệnh đề, giới từ + danh từ", "html": "<table><tr><th>Nghĩa</th><th>Liên từ (+ S + V)</th><th>Giới từ (+ N / V-ing)</th></tr><tr><td>Mặc dù</td><td>although, though, even though</td><td>despite, in spite of</td></tr><tr><td>Bởi vì</td><td>because, since, as</td><td>because of, due to, owing to</td></tr><tr><td>Trong khi</td><td>while</td><td>during</td></tr></table><div class=\"ex\"><span class=\"en\">Although the price was high, many people bought it.</span> <span class=\"vi\">Mặc dù giá cao, nhiều người vẫn mua.</span><br><span class=\"en\">Despite the high price, many people bought it.</span> <span class=\"vi\">Mặc dù giá cao (cụm danh từ)...</span></div>"}, {"h": "unless", "html": "<p><b>unless</b> = <b>if ... not</b> (trừ khi). Sau unless dùng mệnh đề khẳng định.</p><div class=\"ex\"><span class=\"en\">You cannot enter unless you show your ID.</span> <span class=\"vi\">Bạn không thể vào trừ khi xuất trình thẻ.</span></div>"}, {"h": "Liên từ cặp", "html": "<table><tr><th>Cấu trúc</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td>both A and B</td><td>cả A và B</td><td><span class=\"en\">both skills and experience</span></td></tr><tr><td>either A or B</td><td>hoặc A hoặc B</td><td><span class=\"en\">either by card or in cash</span></td></tr><tr><td>neither A nor B</td><td>không A cũng không B</td><td><span class=\"en\">neither fast nor cheap</span></td></tr><tr><td>not only A but also B</td><td>không chỉ A mà còn B</td><td><span class=\"en\">not only cheap but also reliable</span></td></tr></table><div class=\"note\">Thấy 'both' → tìm 'and'; thấy 'either' → tìm 'or'; thấy 'neither' → tìm 'nor'.</div>"}], "tips": ["Nhìn ngay sau chỗ trống: có S + V → liên từ; chỉ có danh từ → giới từ.", "Đọc thêm nghĩa để phân biệt 'mặc dù' và 'bởi vì'."], "mistakes": ["Dùng despite + mệnh đề (Despite it rained) – sửa: Although it rained / Despite the rain.", "Dùng because + danh từ (because the rain) – sửa: because of the rain.", "Ghép sai cặp (both ... or) – sửa: both ... and."], "quiz": [{"q": "____ the heavy rain, the outdoor event was a success.", "opts": ["Although", "Despite", "Because", "Unless"], "a": 1, "ex": "Phía sau là cụm danh từ 'the heavy rain', nghĩa 'mặc dù' → Despite."}, {"q": "____ the price was high, many customers bought the product.", "opts": ["Although", "Despite", "Because of", "During"], "a": 0, "ex": "Phía sau là mệnh đề (the price was high), nghĩa 'mặc dù' → Although."}, {"q": "The flight was delayed ____ bad weather.", "opts": ["because", "because of", "although", "unless"], "a": 1, "ex": "Sau chỗ trống là cụm danh từ 'bad weather', nghĩa 'bởi vì' → because of."}, {"q": "Please do not use your phone ____ the presentation.", "opts": ["while", "although", "because", "during"], "a": 3, "ex": "'the presentation' là danh từ → giới từ during. 'while' cần mệnh đề."}, {"q": "You cannot enter the building ____ you show your ID card.", "opts": ["despite", "unless", "because of", "during"], "a": 1, "ex": "Phía sau là mệnh đề, nghĩa 'trừ khi' → unless. Các đáp án còn lại là giới từ."}, {"q": "The position requires both experience ____ strong communication skills.", "opts": ["or", "nor", "and", "but"], "a": 2, "ex": "Cặp cố định: both ... and."}, {"q": "Customers can pay either by credit card ____ by bank transfer.", "opts": ["and", "or", "nor", "but"], "a": 1, "ex": "Cặp cố định: either ... or."}, {"q": "Mr. Ho read his emails ____ he was waiting for the train.", "opts": ["during", "despite", "while", "because of"], "a": 2, "ex": "Phía sau là mệnh đề (he was waiting...), nghĩa 'trong khi' → while."}]}, {"id": "menh-de-quan-he", "group": "Ngữ pháp", "title": "Mệnh đề quan hệ (who, which, that, whose, where)", "level": 2, "mins": 10, "why": "Câu dài trong Part 5, 6, 7 thường có mệnh đề quan hệ. Part 5 hay hỏi chọn who/which/whose; hiểu cấu trúc này cũng giúp đọc nhanh Part 7.", "sections": [{"h": "Các đại từ quan hệ", "html": "<table><tr><th>Từ</th><th>Thay cho</th><th>Ví dụ</th></tr><tr><td>who</td><td>người (làm chủ ngữ)</td><td><span class=\"en\">the woman <b>who</b> is speaking</span></td></tr><tr><td>which</td><td>vật</td><td><span class=\"en\">the printer <b>which</b> we bought</span></td></tr><tr><td>that</td><td>người hoặc vật (không dùng sau dấu phẩy)</td><td><span class=\"en\">the products <b>that</b> are on sale</span></td></tr><tr><td>whose</td><td>của người/vật đó + danh từ</td><td><span class=\"en\">a designer <b>whose</b> work won awards</span></td></tr><tr><td>where</td><td>nơi chốn (= in/at which)</td><td><span class=\"en\">the hotel <b>where</b> we stayed</span></td></tr></table>"}, {"h": "Cách chọn nhanh", "html": "<ol><li>Nhìn danh từ đứng trước: người hay vật hay nơi chốn?</li><li>Nhìn phía sau: <b>động từ</b> → who/which/that; <b>danh từ</b> → whose; <b>mệnh đề đầy đủ</b> (S + V, không thiếu gì) sau danh từ nơi chốn → where.</li></ol><div class=\"ex\"><span class=\"en\">Applicants who have experience will be preferred.</span> <span class=\"vi\">Ứng viên có kinh nghiệm sẽ được ưu tiên.</span><br><span class=\"en\">This is the city where our factory is located.</span> <span class=\"vi\">Đây là thành phố nơi đặt nhà máy của chúng tôi.</span></div>"}], "tips": ["whose luôn đi liền với một danh từ (whose work, whose office).", "Sau dấu phẩy không dùng that."], "mistakes": ["Dùng which cho người (the man which) – sửa: the man who.", "Dùng where khi phía sau thiếu tân ngữ (the hotel where we booked) – sửa: which/that we booked.", "Thêm đại từ thừa (the printer which we bought it) – bỏ 'it'."], "quiz": [{"q": "The woman ____ is speaking now is our new CEO.", "opts": ["who", "which", "whose", "where"], "a": 0, "ex": "Danh từ chỉ người 'The woman', phía sau là động từ → who."}, {"q": "The printer ____ we bought last month is already broken.", "opts": ["who", "which", "whose", "where"], "a": 1, "ex": "'The printer' là vật, phía sau 'we bought' thiếu tân ngữ → which."}, {"q": "We hired a designer ____ work has won many awards.", "opts": ["who", "which", "whose", "whom"], "a": 2, "ex": "Phía sau là danh từ 'work' (công việc của người thiết kế) → whose."}, {"q": "This is the hotel ____ the conference will take place.", "opts": ["which", "who", "whose", "where"], "a": 3, "ex": "Danh từ nơi chốn, phía sau là mệnh đề đầy đủ 'the conference will take place' → where."}, {"q": "Applicants ____ have more than five years of experience will be preferred.", "opts": ["which", "who", "whose", "where"], "a": 1, "ex": "'Applicants' là người, phía sau là động từ 'have' → who."}, {"q": "The products ____ are displayed in the lobby are on sale.", "opts": ["who", "whose", "that", "where"], "a": 2, "ex": "'The products' là vật, phía sau là động từ → that (có thể thay bằng which)."}, {"q": "The city ____ our main factory is located has good transportation.", "opts": ["where", "which", "who", "whose"], "a": 0, "ex": "Danh từ nơi chốn 'The city', phía sau 'our main factory is located' đầy đủ (không có 'in') → where."}]}, {"id": "to-v-hay-v-ing", "group": "Ngữ pháp", "title": "To V hay V-ing?", "level": 2, "mins": 10, "why": "Part 5 hay cho 4 đáp án như open / to open / opening / opened sau một động từ như plan, avoid. Học thuộc nhóm động từ thường gặp là chọn được ngay.", "sections": [{"h": "Động từ + to V", "html": "<p><span class=\"en\">plan, decide, want, hope, agree, expect, offer, promise, need, fail, intend, aim</span></p><p>Cấu trúc <b>V + sb + to V</b>: <span class=\"en\">ask, encourage, allow, require, invite, remind</span> sb to V (và bị động: <span class=\"en\">be encouraged to V</span>).</p><div class=\"ex\"><span class=\"en\">The company plans to open a new store.</span> <span class=\"vi\">Công ty dự định mở cửa hàng mới.</span><br><span class=\"en\">Staff are required to wear ID cards.</span> <span class=\"vi\">Nhân viên được yêu cầu đeo thẻ.</span></div>"}, {"h": "Động từ + V-ing", "html": "<p><span class=\"en\">avoid, enjoy, finish, consider, suggest, recommend, mind, keep, delay, postpone</span></p><p>Sau <b>giới từ</b> luôn dùng V-ing. Chú ý: <b>look forward to, be committed to, be used to</b> – 'to' ở đây là giới từ → + V-ing.</p><div class=\"ex\"><span class=\"en\">Please avoid making personal calls.</span> <span class=\"vi\">Vui lòng tránh gọi điện cá nhân.</span><br><span class=\"en\">We look forward to seeing you.</span> <span class=\"vi\">Chúng tôi mong được gặp bạn.</span></div>"}, {"h": "Chỉ mục đích: (in order) to V", "html": "<p><b>In order to / To + V</b> = để làm gì.</p><div class=\"ex\"><span class=\"en\">In order to improve service, we hired more staff.</span> <span class=\"vi\">Để cải thiện dịch vụ, chúng tôi tuyển thêm người.</span></div>"}], "tips": ["Học theo cụm: plan to, decide to, avoid -ing, finish -ing.", "Thấy 'look forward to' → chọn V-ing ngay."], "mistakes": ["look forward to see – sửa: look forward to seeing.", "avoid to make – sửa: avoid making.", "Dùng 'for + V' để chỉ mục đích (for improve) – sửa: to improve."], "quiz": [{"q": "The company plans ____ a new store next year.", "opts": ["open", "to open", "opening", "opened"], "a": 1, "ex": "plan + to V → plans to open."}, {"q": "Please avoid ____ personal calls during work hours.", "opts": ["make", "to make", "making", "made"], "a": 2, "ex": "avoid + V-ing → avoid making."}, {"q": "We look forward to ____ you at the event.", "opts": ["seeing", "see", "saw", "seen"], "a": 0, "ex": "'to' trong look forward to là giới từ → + V-ing: seeing."}, {"q": "Ms. Ngoc decided ____ the job offer.", "opts": ["accepting", "accepted", "accept", "to accept"], "a": 3, "ex": "decide + to V → decided to accept."}, {"q": "Mr. Bao finished ____ the report at 6 P.M.", "opts": ["write", "to write", "writing", "written"], "a": 2, "ex": "finish + V-ing → finished writing."}, {"q": "____ improve customer service, the company hired more staff.", "opts": ["Because", "In order to", "Although", "So that"], "a": 1, "ex": "Chỉ mục đích + động từ nguyên mẫu 'improve' → In order to. Because/Although/So that cần mệnh đề."}, {"q": "Employees are encouraged ____ the training sessions.", "opts": ["attending", "attended", "to attend", "attend"], "a": 2, "ex": "be encouraged + to V → are encouraged to attend."}, {"q": "Would you mind ____ the door, please?", "opts": ["close", "to close", "closed", "closing"], "a": 3, "ex": "mind + V-ing → mind closing."}]}, {"id": "so-sanh", "group": "Ngữ pháp", "title": "So sánh hơn, nhất, bằng", "level": 2, "mins": 10, "why": "Part 5 hay gài dấu hiệu 'than', 'the ... of all', 'as ... as' để kiểm tra dạng so sánh. Part 7 cũng có câu hỏi so sánh giá, số liệu.", "sections": [{"h": "Công thức", "html": "<table><tr><th>Loại</th><th>Tính từ ngắn</th><th>Tính từ dài</th><th>Dấu hiệu</th></tr><tr><td>So sánh hơn</td><td>adj-er + than</td><td>more + adj + than</td><td>than</td></tr><tr><td>So sánh nhất</td><td>the + adj-est</td><td>the most + adj</td><td>the, of all, in the city, ever</td></tr><tr><td>So sánh bằng</td><td>as + adj + as</td><td>as + adj + as</td><td>as ... as</td></tr></table><div class=\"ex\"><span class=\"en\">Sales are higher than last year.</span> <span class=\"vi\">Doanh số cao hơn năm ngoái.</span><br><span class=\"en\">This is the most expensive hotel in the city.</span> <span class=\"vi\">Đây là khách sạn đắt nhất thành phố.</span><br><span class=\"en\">The new model is as reliable as the old one.</span> <span class=\"vi\">Mẫu mới đáng tin cậy như mẫu cũ.</span></div>"}, {"h": "Bất quy tắc và từ nhấn mạnh", "html": "<table><tr><th>Gốc</th><th>Hơn</th><th>Nhất</th></tr><tr><td>good / well</td><td>better</td><td>best</td></tr><tr><td>bad</td><td>worse</td><td>worst</td></tr><tr><td>many / much</td><td>more</td><td>most</td></tr><tr><td>little</td><td>less</td><td>least</td></tr></table><p>Nhấn mạnh so sánh hơn: <b>much, far, even, significantly</b> + better (KHÔNG dùng very).</p>"}, {"h": "Càng ... càng", "html": "<p><b>The + so sánh hơn ..., the + so sánh hơn ...</b></p><div class=\"ex\"><span class=\"en\">The more you order, the bigger the discount.</span> <span class=\"vi\">Bạn đặt càng nhiều, giảm giá càng lớn.</span></div>"}], "tips": ["Thấy 'than' → so sánh hơn; thấy 'as ... as' → để nguyên tính từ/trạng từ.", "Bổ nghĩa động từ thì so sánh trạng từ: more efficiently, not more efficient."], "mistakes": ["more cheaper – sửa: cheaper (không dùng more với -er).", "very better – sửa: much better.", "as cheap than – sửa: as cheap as / cheaper than."], "quiz": [{"q": "This year's sales are ____ than last year's.", "opts": ["high", "higher", "highest", "more high"], "a": 1, "ex": "Có 'than', tính từ ngắn → higher."}, {"q": "This is the ____ hotel in the city.", "opts": ["expensive", "more expensive", "most expensive", "expensively"], "a": 2, "ex": "Có 'the ... in the city' → so sánh nhất, tính từ dài → the most expensive."}, {"q": "The new model is as ____ as the old one.", "opts": ["reliable", "more reliable", "most reliable", "reliably"], "a": 0, "ex": "as + tính từ nguyên mẫu + as → as reliable as (sau 'is' cần tính từ)."}, {"q": "The new printer works ____ than the old one.", "opts": ["efficient", "more efficient", "more efficiently", "most efficiently"], "a": 2, "ex": "Bổ nghĩa động từ 'works' cần trạng từ, có 'than' → more efficiently."}, {"q": "The ____ you order, the bigger the discount you get.", "opts": ["much", "most", "more", "many"], "a": 2, "ex": "Cấu trúc 'càng ... càng': The more ..., the bigger ..."}, {"q": "Our service is ____ better than our competitors'.", "opts": ["very", "much", "more", "most"], "a": 1, "ex": "Nhấn mạnh so sánh hơn dùng 'much', không dùng 'very' → much better."}, {"q": "Of all the candidates, Ms. Yen is the ____ qualified.", "opts": ["much", "more", "very", "most"], "a": 3, "ex": "'Of all ... the' → so sánh nhất: the most qualified."}, {"q": "The second floor is ____ the first floor.", "opts": ["smaller than", "smaller as", "as small than", "the smallest than"], "a": 0, "ex": "So sánh hơn: adj-er + than → smaller than."}]}, {"id": "cau-dieu-kien", "group": "Ngữ pháp", "title": "Câu điều kiện loại 1, 2 và đảo ngữ 'Should you...'", "level": 3, "mins": 12, "why": "Email và thông báo trong TOEIC rất hay kết thúc bằng 'Should you have any questions, please...'. Part 5 kiểm tra dạng động từ trong câu if và câu đảo ngữ này.", "sections": [{"h": "Loại 1: có thể xảy ra", "html": "<p><b>If + S + V (hiện tại đơn), S + will/can + V</b></p><div class=\"ex\"><span class=\"en\">If the shipment arrives late, we will call the customer.</span> <span class=\"vi\">Nếu hàng đến trễ, chúng tôi sẽ gọi khách hàng.</span><br><span class=\"en\">If you register today, you can get a discount.</span> <span class=\"vi\">Nếu đăng ký hôm nay, bạn được giảm giá.</span></div>"}, {"h": "Loại 2: không có thật ở hiện tại", "html": "<p><b>If + S + V2/were, S + would/could + V</b> (với động từ <b>be</b>, dùng <b>were</b> cho mọi chủ ngữ)</p><div class=\"ex\"><span class=\"en\">If I had more time, I would join the project.</span> <span class=\"vi\">Nếu tôi có nhiều thời gian hơn (thật ra không có), tôi sẽ tham gia.</span><br><span class=\"en\">If the price were lower, more people would buy it.</span> <span class=\"vi\">Nếu giá thấp hơn, nhiều người sẽ mua hơn.</span></div>"}, {"h": "Đảo ngữ với Should (loại 1)", "html": "<p>Bỏ <b>if</b>, đưa <b>should</b> lên đầu, động từ để <b>nguyên mẫu</b>:</p><table><tr><th>Câu if</th><th>Đảo ngữ</th></tr><tr><td><span class=\"en\">If you have any questions, ...</span></td><td><span class=\"en\"><b>Should</b> you <b>have</b> any questions, ...</span></td></tr><tr><td><span class=\"en\">If the item arrives damaged, ...</span></td><td><span class=\"en\"><b>Should</b> the item <b>arrive</b> damaged, ...</span></td></tr></table><div class=\"note\">Mẫu câu kinh điển: <span class=\"en\">Should you have any questions, please contact us.</span> <span class=\"vi\">Nếu có câu hỏi, vui lòng liên hệ chúng tôi.</span></div>"}], "tips": ["Mệnh đề if loại 1 không dùng will.", "Thấy 'Should you ____' → chọn động từ nguyên mẫu (have, need, experience...)."], "mistakes": ["If it will rain... – sửa: If it rains...", "Should you having/had... – sửa: Should you have...", "Trộn loại 1 và 2 (If I had time, I will go) – sửa: I would go."], "quiz": [{"q": "If the shipment arrives late, we ____ the customer immediately.", "opts": ["calling", "will call", "called", "would called"], "a": 1, "ex": "Loại 1: If + hiện tại đơn (arrives), mệnh đề chính dùng will + V → will call."}, {"q": "If I ____ more time, I would join the project team.", "opts": ["had", "have", "will have", "having"], "a": 0, "ex": "Mệnh đề chính có 'would' → loại 2, mệnh đề if dùng quá khứ → had."}, {"q": "____ you have any questions, please contact our support team.", "opts": ["Would", "Unless", "Should", "Had"], "a": 2, "ex": "Đảo ngữ điều kiện loại 1: Should + S + V nguyên mẫu = If you have any questions."}, {"q": "If the price were lower, more customers ____ the product.", "opts": ["will buy", "buy", "bought", "would buy"], "a": 3, "ex": "Mệnh đề if dùng 'were' → loại 2, mệnh đề chính: would + V → would buy."}, {"q": "Should you ____ any problems with the device, call this number.", "opts": ["experience", "experienced", "experiencing", "to experience"], "a": 0, "ex": "Sau 'Should + S' dùng động từ nguyên mẫu → experience."}, {"q": "We will cancel the order unless the payment ____ by Friday.", "opts": ["receives", "is received", "will be received", "received"], "a": 1, "ex": "'unless' giống 'if...not' nên dùng hiện tại đơn; tiền thanh toán 'được nhận' → bị động: is received."}, {"q": "If Mr. Duc ____ the manager, he would change the policy.", "opts": ["is", "will be", "were", "be"], "a": 2, "ex": "Mệnh đề chính có 'would' → loại 2; với 'be' dùng 'were' cho mọi chủ ngữ."}]}, {"id": "phan-tu-lam-tinh-tu", "group": "Ngữ pháp", "title": "Phân từ làm tính từ (-ing / -ed) và rút gọn mệnh đề", "level": 3, "mins": 12, "why": "Part 5 hay cho cặp interesting/interested, satisfying/satisfied, và các cụm rút gọn như 'the documents attached', 'employees wishing to...'. Đây là dạng câu khó nhưng có quy tắc rõ ràng.", "sections": [{"h": "-ing hay -ed?", "html": "<table><tr><th>Dạng</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td>V-ing</td><td>gây ra cảm xúc / bản chất của vật</td><td><span class=\"en\">a <b>boring</b> meeting</span> <span class=\"vi\">cuộc họp gây chán</span></td></tr><tr><td>V-ed</td><td>người cảm thấy (bị tác động)</td><td><span class=\"en\">The staff felt <b>bored</b>.</span> <span class=\"vi\">Nhân viên thấy chán</span></td></tr></table><p>Cặp thường gặp: <span class=\"en\">interesting/interested, satisfying/satisfied, exciting/excited, surprising/surprised, disappointing/disappointed</span></p>"}, {"h": "Rút gọn mệnh đề quan hệ", "html": "<table><tr><th>Dạng</th><th>Khi nào</th><th>Ví dụ</th></tr><tr><td>N + V-ing</td><td>Chủ động (danh từ tự làm)</td><td><span class=\"en\">employees <b>wishing</b> to attend</span> = who wish to attend</td></tr><tr><td>N + V3/V-ed</td><td>Bị động (danh từ bị/được làm)</td><td><span class=\"en\">the documents <b>attached</b></span> = which are attached</td></tr></table><div class=\"ex\"><span class=\"en\">Employees wishing to attend should register online.</span> <span class=\"vi\">Nhân viên muốn tham dự nên đăng ký trực tuyến.</span><br><span class=\"en\">Please review the documents attached to this email.</span> <span class=\"vi\">Vui lòng xem tài liệu đính kèm trong email này.</span><br><span class=\"en\">Products made in this factory are exported.</span> <span class=\"vi\">Sản phẩm được làm ở nhà máy này được xuất khẩu.</span></div>"}, {"h": "Cách chọn nhanh", "html": "<ol><li>Danh từ đứng trước có <b>tự làm</b> hành động không? Có → V-ing. Không (bị/được) → V3.</li><li>Phía sau còn tân ngữ hoặc 'to V' cho động từ đó → thường là V-ing; phía sau có 'by' hoặc không có tân ngữ → thường là V3.</li></ol>"}], "tips": ["Người + cảm xúc → -ed (I am interested). Vật/sự việc → -ing (an interesting offer).", "interested in, satisfied with, attached to: học theo cụm."], "mistakes": ["I am interesting in this job – sửa: I am interested in.", "the documents attaching – sửa: the documents attached.", "Dùng động từ chia trong cụm rút gọn (employees wish to attend should...) – sửa: wishing."], "quiz": [{"q": "The results of the customer survey were very ____.", "opts": ["surprise", "surprising", "surprised", "surprisingly"], "a": 1, "ex": "Chủ ngữ là vật (results) gây ra cảm xúc → surprising (gây ngạc nhiên)."}, {"q": "The staff were ____ with the new bonus policy.", "opts": ["satisfied", "satisfy", "satisfying", "satisfaction"], "a": 0, "ex": "Người cảm thấy hài lòng, cụm 'satisfied with' → satisfied."}, {"q": "Please review the documents ____ to this email.", "opts": ["attach", "attaching", "attached", "attachment"], "a": 2, "ex": "Tài liệu 'được đính kèm' (bị động) → rút gọn bằng V3: attached."}, {"q": "Employees ____ to attend the workshop should register online.", "opts": ["wish", "wishing", "wished", "wishes"], "a": 1, "ex": "Câu đã có động từ chính 'should register'; nhân viên tự 'muốn' (chủ động) → rút gọn bằng V-ing: wishing."}, {"q": "The meeting was long and ____.", "opts": ["bored", "bore", "boredom", "boring"], "a": 3, "ex": "Cuộc họp (sự việc) gây chán → boring. 'bored' dùng cho người cảm thấy chán."}, {"q": "The products ____ in this factory are exported to Japan.", "opts": ["made", "making", "make", "makes"], "a": 0, "ex": "Sản phẩm 'được làm ra' (bị động), câu đã có động từ chính 'are exported' → V3: made."}, {"q": "We have an ____ offer for our loyal customers.", "opts": ["excite", "exciting", "excited", "excitement"], "a": 1, "ex": "Lời đề nghị (vật) gây hào hứng, đứng trước danh từ 'offer' → exciting."}, {"q": "Customers ____ in the program will receive monthly updates.", "opts": ["interest", "interesting", "interested", "interests"], "a": 2, "ex": "Khách hàng (người) quan tâm, cụm 'interested in' → interested."}]}, {"id": "part-1-ta-tranh", "group": "Nghe", "title": "Part 1 – Tả tranh", "level": 1, "mins": 12, "why": "Part 1 có 6 câu và là phần dễ lấy điểm nhất. Chỉ cần nắm từ vựng hành động, vị trí và phân biệt hai dạng bị động là bạn có thể làm đúng gần hết.", "sections": [{"h": "Từ vựng tư thế và hành động của người", "html": "<table><tr><th>Từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td>stand / sit / kneel</td><td>đứng / ngồi / quỳ</td><td><span class=\"en\">A man is kneeling beside a car.</span><br><span class=\"vi\">Một người đàn ông đang quỳ cạnh chiếc xe.</span></td></tr><tr><td>lean against</td><td>dựa vào</td><td><span class=\"en\">She is leaning against a railing.</span><br><span class=\"vi\">Cô ấy đang dựa vào lan can.</span></td></tr><tr><td>reach for</td><td>với tay lấy</td><td><span class=\"en\">He is reaching for a bottle.</span><br><span class=\"vi\">Anh ấy đang với tay lấy cái chai.</span></td></tr><tr><td>carry / hold</td><td>mang, xách / cầm</td><td><span class=\"en\">A worker is carrying a ladder.</span><br><span class=\"vi\">Một công nhân đang vác cái thang.</span></td></tr><tr><td>look at / examine</td><td>nhìn / xem xét kỹ</td><td><span class=\"en\">They are examining a map.</span><br><span class=\"vi\">Họ đang xem kỹ một tấm bản đồ.</span></td></tr><tr><td>wipe / sweep / water</td><td>lau / quét / tưới</td><td><span class=\"en\">A woman is watering some flowers.</span><br><span class=\"vi\">Một người phụ nữ đang tưới hoa.</span></td></tr></table>"}, {"h": "Từ vựng vị trí đồ vật", "html": "<table><tr><th>Cụm từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td>next to / beside</td><td>bên cạnh</td><td><span class=\"en\">A lamp is next to the sofa.</span><br><span class=\"vi\">Cây đèn ở cạnh ghế sofa.</span></td></tr><tr><td>on top of</td><td>ở trên cùng</td><td><span class=\"en\">A box is on top of the cabinet.</span><br><span class=\"vi\">Cái hộp ở trên nóc tủ.</span></td></tr><tr><td>stacked / piled</td><td>xếp chồng / chất đống</td><td><span class=\"en\">Plates are stacked on the counter.</span><br><span class=\"vi\">Đĩa được xếp chồng trên quầy.</span></td></tr><tr><td>lined up / in a row</td><td>xếp thành hàng</td><td><span class=\"en\">Bicycles are lined up outside.</span><br><span class=\"vi\">Xe đạp được xếp thành hàng bên ngoài.</span></td></tr><tr><td>hanging on</td><td>treo trên</td><td><span class=\"en\">A clock is hanging on the wall.</span><br><span class=\"vi\">Một chiếc đồng hồ treo trên tường.</span></td></tr></table>"}, {"h": "Thì hiện tại tiếp diễn: người đang làm gì", "html": "<div class=\"ex\"><b>Công thức:</b> S + am / is / are + V-ing</div><ul><li><span class=\"en\">The man is pushing a cart.</span> – <span class=\"vi\">Người đàn ông đang đẩy xe.</span></li><li><span class=\"en\">Some people are waiting in line.</span> – <span class=\"vi\">Vài người đang xếp hàng chờ.</span></li></ul><p>Khi tranh có người, đáp án thường dùng thì này. Hãy kiểm tra cả <b>động từ</b> (hành động) và <b>danh từ</b> (đồ vật) đều phải đúng với tranh.</p>"}, {"h": "Bị động: đang được làm hay đã ở trạng thái đó?", "html": "<table><tr><th>Cấu trúc</th><th>Ý nghĩa</th><th>Ví dụ</th></tr><tr><td><b>is / are being + V3</b></td><td>Đang có người làm việc đó → <b>trong tranh phải có người</b></td><td><span class=\"en\">The windows are being cleaned.</span><br><span class=\"vi\">Cửa sổ đang được (ai đó) lau.</span></td></tr><tr><td><b>has / have been + V3</b><br><b>is / are + V3</b></td><td>Trạng thái đã có sẵn → tranh <b>không cần có người</b></td><td><span class=\"en\">The windows have been cleaned.</span><br><span class=\"vi\">Cửa sổ đã được lau (sạch rồi).</span></td></tr></table><div class=\"note\">Tranh chỉ có đồ vật, không có người → gần như loại hết các câu \"is/are being + V3\". Ngoại lệ hay gặp: <span class=\"en\">Some items are being displayed.</span> (<span class=\"vi\">Hàng hóa đang được trưng bày</span>) vẫn có thể dùng để tả trạng thái.</div>"}], "tips": ["Trước khi băng đọc, nhìn tranh 3–5 giây và tự hỏi: có người không, họ đang làm gì, đồ vật ở đâu.", "Nghe từng đáp án và loại ngay câu sai, giữ lại câu \"có vẻ đúng\" rồi so sánh.", "Câu tả chung chung nhưng đúng thường là đáp án hơn câu tả chi tiết mà sai một chữ."], "mistakes": ["Nghe thấy tên đồ vật có trong tranh là chọn ngay → phải kiểm tra cả động từ và vị trí.", "Chọn \"are being + V3\" cho tranh không có người → dạng này cần có người đang làm.", "Nhầm \"wearing\" (đang mặc, trạng thái) với \"putting on\" (đang mặc vào, hành động)."], "quiz": [{"q": "Tranh: kệ đầy sách, không có người. Câu nào tả đúng nhất?", "opts": ["The shelves are being painted.", "Some books have been placed on the shelves.", "A man is reading a book.", "Some books are being arranged on the shelves."], "a": 1, "ex": "Tranh không có người nên không dùng \"are being + V3\". \"have been placed\" tả trạng thái sách đã được đặt sẵn trên kệ."}, {"q": "The man is ____ a heavy box up the stairs.", "opts": ["carry", "carries", "carried", "carrying"], "a": 3, "ex": "Sau \"is\" để tả hành động đang diễn ra cần V-ing: is carrying (đang mang)."}, {"q": "\"The tables are being wiped.\" nghĩa là gì?", "opts": ["Bàn đang được dọn đi chỗ khác", "Bàn đã được lau xong", "Có người đang lau bàn", "Bàn đang bị bẩn"], "a": 2, "ex": "\"are being + V3\" = đang được làm, tức là có người đang lau bàn ngay lúc chụp ảnh."}, {"q": "\"lean against\" nghĩa là gì?", "opts": ["dựa vào", "với tay lấy", "quỳ xuống", "xếp thành hàng"], "a": 0, "ex": "lean against = dựa vào. \"Với tay lấy\" là reach for, \"xếp thành hàng\" là lined up."}, {"q": "Tranh: một chiếc xe đạp dựng cạnh bức tường, không có ai. Câu nào chắc chắn SAI?", "opts": ["A bicycle is leaning against a wall.", "A bicycle has been left near a wall.", "There is a bicycle by the wall.", "A bicycle is being repaired."], "a": 3, "ex": "\"is being repaired\" nghĩa là có người đang sửa xe, nhưng tranh không có ai. Ba câu còn lại đều tả đúng trạng thái."}, {"q": "\"Chairs are stacked in the corner.\" nghĩa là gì?", "opts": ["Ghế được xếp thành hàng giữa phòng", "Ghế được xếp chồng lên nhau ở góc phòng", "Ghế bị hỏng ở góc phòng", "Ghế đang được ai đó mang đi"], "a": 1, "ex": "stacked = xếp chồng; in the corner = ở góc. \"are + V3\" tả trạng thái, không cần có người."}, {"q": "Some plants ____ on the windowsill.", "opts": ["have been placed", "is placed", "are placing", "placing"], "a": 0, "ex": "Cây không tự đặt được nên cần bị động. Chủ ngữ số nhiều (plants) nên dùng \"have been placed\". \"is placed\" sai vì chủ ngữ số nhiều, \"placing\" thiếu động từ to be."}, {"q": "Tranh: người phụ nữ đang mặc sẵn áo khoác, đứng ở trạm xe buýt. Câu nào đúng?", "opts": ["She is taking off a jacket.", "She is hanging up a jacket.", "She is wearing a jacket.", "She is putting on a jacket."], "a": 2, "ex": "wearing = đang mặc (trạng thái). putting on = đang mặc vào, taking off = đang cởi ra, hanging up = đang treo lên: đều là hành động không có trong tranh."}]}, {"id": "part-2-hoi-dap", "group": "Nghe", "title": "Part 2 – Hỏi đáp", "level": 1, "mins": 14, "why": "Part 2 có 25 câu, chiếm 1/4 phần Nghe. Chỉ cần nghe rõ từ để hỏi ở đầu câu và tránh bẫy âm là bạn đã loại được phần lớn đáp án sai.", "sections": [{"h": "Nghe kỹ từ để hỏi ở đầu câu", "html": "<table><tr><th>Từ để hỏi</th><th>Hỏi về</th><th>Câu trả lời hợp lý</th></tr><tr><td>Who</td><td>người</td><td><span class=\"en\">Mr. Park from Sales.</span></td></tr><tr><td>When</td><td>thời gian</td><td><span class=\"en\">Next Monday.</span> / <span class=\"en\">After lunch.</span></td></tr><tr><td>Where</td><td>nơi chốn</td><td><span class=\"en\">In the lobby.</span> / <span class=\"en\">On the third floor.</span></td></tr><tr><td>Why</td><td>lý do</td><td><span class=\"en\">Because the road was closed.</span> / <span class=\"en\">To meet a client.</span></td></tr><tr><td>How long / How often / How much</td><td>bao lâu / bao nhiêu lần / bao nhiêu tiền</td><td><span class=\"en\">About two hours.</span> / <span class=\"en\">Twice a week.</span> / <span class=\"en\">Twenty dollars.</span></td></tr><tr><td>What / Which</td><td>cái gì / cái nào</td><td><span class=\"en\">The blue one.</span></td></tr></table><div class=\"note\">Hay nhầm: <b>When</b> và <b>Where</b> nghe gần giống nhau. Hãy tập trung vào 2–3 từ đầu tiên.</div>"}, {"h": "Câu Yes/No và câu đề nghị, lời mời", "html": "<p><b>Câu Yes/No</b> (Do/Does/Did, Is/Are, Have/Has, Can...): đáp án có thể bắt đầu bằng Yes/No, nhưng <b>cũng có thể không</b>.</p><div class=\"ex\"><span class=\"en\">Did you finish the slides?</span> → <span class=\"en\">Almost. I need ten more minutes.</span><br><span class=\"vi\">Bạn làm xong slide chưa? → Gần xong rồi, mình cần thêm mười phút.</span></div><table><tr><th>Mẫu câu</th><th>Chức năng</th><th>Cách đáp hay gặp</th></tr><tr><td>Why don't we / Why don't you...?</td><td>Gợi ý (KHÔNG hỏi lý do)</td><td><span class=\"en\">Good idea.</span> / <span class=\"en\">Sure, let's do that.</span></td></tr><tr><td>Would you like (me) to...?</td><td>Mời / đề nghị giúp</td><td><span class=\"en\">Yes, thanks.</span> / <span class=\"en\">No, I can manage.</span></td></tr><tr><td>Could you / Can you...?</td><td>Nhờ vả</td><td><span class=\"en\">Of course.</span> / <span class=\"en\">Sorry, I'm busy right now.</span></td></tr></table><p>Câu \"Why don't we...?\" mà đáp án bắt đầu bằng \"Because...\" thường là <b>bẫy</b>.</p>"}, {"h": "Bẫy âm giống nhau và lặp từ", "html": "<ul><li><b>Âm giống nhau:</b> câu hỏi có <i>copy</i>, đáp án sai có <i>coffee</i>; câu hỏi có <i>break</i>, đáp án sai có <i>broken</i>.</li><li><b>Lặp lại từ:</b> đáp án sai lặp lại đúng một từ trong câu hỏi nhưng nghĩa không liên quan.</li></ul><div class=\"ex\"><span class=\"en\">Where can I print this report?</span><br>✗ <span class=\"en\">The report is very long.</span> (lặp từ report, không trả lời Where)<br>✓ <span class=\"en\">There's a printer near the kitchen.</span></div>"}, {"h": "Câu trả lời gián tiếp: thường là đáp án đúng", "html": "<p>Người bản xứ hay không trả lời thẳng. Các câu sau gần như hợp với <b>mọi loại câu hỏi</b>:</p><ul><li><span class=\"en\">I'm not sure.</span> – <span class=\"vi\">Mình không chắc.</span></li><li><span class=\"en\">Let me check.</span> – <span class=\"vi\">Để mình kiểm tra.</span></li><li><span class=\"en\">You should ask Ms. Lee.</span> – <span class=\"vi\">Bạn nên hỏi cô Lee.</span></li><li><span class=\"en\">It hasn't been decided yet.</span> – <span class=\"vi\">Việc đó chưa được quyết định.</span></li></ul><div class=\"ex\"><span class=\"en\">When does the new manager start?</span> → <span class=\"en\">They haven't announced it yet.</span><br><span class=\"vi\">Khi nào quản lý mới bắt đầu làm? → Họ chưa thông báo.</span></div>"}], "tips": ["Viết nhanh chữ cái đầu của từ để hỏi (W = Where, Wn = When...) ra nháp nếu hay quên.", "Dùng cách loại trừ: chỉ cần loại được 2 câu sai là chọn được đáp án.", "Đáp án nghe \"lạ\", không trả lời thẳng nhưng hợp lý thì thường là đáp án đúng."], "mistakes": ["Chọn đáp án có từ giống câu hỏi → đáp án lặp từ thường là bẫy.", "Nghe \"Why don't we...\" rồi chọn đáp án \"Because...\" → đây là câu gợi ý, không hỏi lý do.", "Nghĩ câu Yes/No bắt buộc trả lời Yes/No → đáp án đúng có thể không có hai từ này.", "Nhầm When với Where → tập nghe kỹ âm đầu và nhìn loại câu trả lời (thời gian hay nơi chốn)."], "quiz": [{"q": "\"Where is the staff meeting being held?\" Câu trả lời nào đúng?", "opts": ["At three o'clock.", "Yes, I met him there.", "In Conference Room B."], "a": 2, "ex": "Where hỏi nơi chốn → \"In Conference Room B\". \"At three o'clock\" trả lời When; \"met\" là bẫy âm với \"meeting\"."}, {"q": "\"When will the new printer arrive?\" Câu trả lời nào đúng?", "opts": ["It prints in color.", "By Thursday afternoon.", "On the second floor."], "a": 1, "ex": "When hỏi thời gian → \"By Thursday afternoon\". \"On the second floor\" trả lời Where; \"prints\" lặp từ gốc của printer."}, {"q": "\"Who is in charge of the budget report?\" Câu trả lời nào đúng?", "opts": ["Ms. Tran from Accounting.", "Yes, it's a large budget.", "It's due next week."], "a": 0, "ex": "Who hỏi người → \"Ms. Tran from Accounting\". Câu Wh- không trả lời bằng Yes, và \"budget\" chỉ là lặp từ."}, {"q": "\"Why don't we take a short break?\" Câu trả lời nào đúng?", "opts": ["It took two hours.", "Because it's broken.", "That's a good idea."], "a": 2, "ex": "\"Why don't we...\" là lời gợi ý → đồng ý \"That's a good idea\". \"Because...\" là bẫy; \"broken\" là bẫy âm với \"break\"."}, {"q": "\"Would you like me to send you the file?\" Câu trả lời nào đúng?", "opts": ["I filed it yesterday.", "Yes, that would be helpful.", "It's very light."], "a": 1, "ex": "Đây là lời đề nghị giúp → nhận lời \"Yes, that would be helpful\". \"filed\" là lặp từ nhưng khác nghĩa (sắp xếp hồ sơ)."}, {"q": "\"Has the client signed the contract yet?\" Câu trả lời nào đúng?", "opts": ["A contract worker.", "Sign here, please.", "I'll have to check with the legal team."], "a": 2, "ex": "Câu trả lời gián tiếp: \"Mình phải hỏi lại bộ phận pháp lý\" là hợp lý. Hai câu kia lặp từ contract / sign nhưng không trả lời câu hỏi."}, {"q": "\"How long does it take to get to the airport?\" Câu trả lời nào đúng?", "opts": ["Three flights a day.", "It's a long report.", "About forty minutes by taxi."], "a": 2, "ex": "How long hỏi thời gian kéo dài → \"About forty minutes\". \"Three flights a day\" trả lời How often; \"long\" là lặp từ."}, {"q": "Trong Part 2, loại đáp án nào thường là BẪY?", "opts": ["Đáp án \"Let me check.\"", "Đáp án hỏi ngược lại để làm rõ", "Đáp án nêu thời gian cho câu hỏi When", "Đáp án có từ phát âm giống từ trong câu hỏi nhưng nghĩa không liên quan"], "a": 3, "ex": "Bẫy âm giống và bẫy lặp từ là hai bẫy phổ biến nhất. \"Let me check\" và câu hỏi ngược lại thường là đáp án đúng."}]}, {"id": "part-3-4-hoi-thoai-bai-noi", "group": "Nghe", "title": "Part 3–4 – Hội thoại và bài nói", "level": 2, "mins": 14, "why": "Part 3 và Part 4 có tổng 69 câu, gần 70% phần Nghe. Biết đọc trước câu hỏi và nhận ra cách diễn đạt khác (paraphrase) là chìa khóa để tăng điểm Nghe.", "sections": [{"h": "Quy trình 3 bước cho mỗi đoạn", "html": "<ol><li><b>Đọc trước 3 câu hỏi</b> (và lướt đáp án nếu kịp) trước khi đoạn nghe bắt đầu.</li><li><b>Gạch từ khóa</b>: từ để hỏi + người được hỏi (man / woman / speaker) + danh từ, động từ chính.</li><li><b>Vừa nghe vừa chọn</b>: đáp án xuất hiện lần lượt theo thứ tự câu hỏi. Chọn xong câu nào chuyển ngay sang câu tiếp.</li></ol><div class=\"ex\"><span class=\"en\">What does the <b>woman</b> <b>ask</b> the man to <b>do</b>?</span><br><span class=\"vi\">→ Chờ nghe người phụ nữ nói câu nhờ vả: Could you... / Please... / Can you...</span></div><div class=\"note\">Khi băng đang đọc 3 câu hỏi của đoạn hiện tại, hãy chuyển mắt sang đọc trước câu hỏi của đoạn tiếp theo.</div>"}, {"h": "Câu hỏi chung và câu hỏi chi tiết", "html": "<table><tr><th>Loại</th><th>Ví dụ câu hỏi</th><th>Đáp án thường nằm ở</th></tr><tr><td>Câu hỏi chung</td><td><span class=\"en\">What is the conversation mainly about?</span><br><span class=\"en\">Where most likely are the speakers?</span><br><span class=\"en\">Who most likely is the speaker?</span></td><td>1–2 câu đầu bài</td></tr><tr><td>Câu hỏi chi tiết</td><td><span class=\"en\">What problem does the man mention?</span><br><span class=\"en\">When will the order arrive?</span></td><td>giữa bài</td></tr><tr><td>Việc sẽ làm tiếp</td><td><span class=\"en\">What will the woman probably do next?</span></td><td>cuối bài (I'll... / Let me...)</td></tr></table>"}, {"h": "Nhận diện paraphrase (nói cách khác)", "html": "<p>Đáp án đúng hiếm khi lặp lại đúng từ trong bài nghe. Nó thường <b>nói lại cùng ý bằng từ khác</b>.</p><table><tr><th>Trong bài nghe</th><th>Trong đáp án</th><th>Nghĩa</th></tr><tr><td><span class=\"en\">The copier isn't working.</span></td><td><span class=\"en\">A machine is broken.</span></td><td>Máy bị hỏng</td></tr><tr><td><span class=\"en\">I'll email you the price list.</span></td><td><span class=\"en\">Send some information</span></td><td>Gửi thông tin</td></tr><tr><td><span class=\"en\">The train was pushed back an hour.</span></td><td><span class=\"en\">A departure was delayed.</span></td><td>Chuyến đi bị hoãn</td></tr><tr><td><span class=\"en\">We're short-staffed today.</span></td><td><span class=\"en\">There are not enough workers.</span></td><td>Thiếu nhân viên</td></tr></table><div class=\"note\">Đáp án lặp lại y nguyên một từ trong bài nghe chưa chắc đúng. Hãy kiểm tra xem ý có khớp không.</div>"}], "tips": ["Lỡ một câu thì chọn đoán ngay rồi tập trung đọc câu hỏi của đoạn sau, đừng tiếc câu cũ.", "Để ý người được hỏi: câu hỏi về \"the man\" thì đáp án thường nằm trong lời người đàn ông.", "Câu hỏi về nghề nghiệp hay nơi chốn: nghe các từ gợi ý như patient (→ phòng khám), boarding (→ sân bay)."], "mistakes": ["Nghe xong cả đoạn rồi mới đọc câu hỏi → phải đọc câu hỏi trước khi nghe.", "Chọn đáp án vì nghe thấy một từ giống y bài → đáp án đúng thường là paraphrase.", "Cố dịch từng từ khi nghe → chỉ cần bắt từ khóa trả lời câu hỏi đã đọc trước."], "quiz": [{"q": "Câu hỏi \"Where most likely are the speakers?\" thuộc loại nào?", "opts": ["Câu hỏi về con số", "Câu hỏi về việc sẽ làm tiếp", "Câu hỏi chi tiết", "Câu hỏi chung"], "a": 3, "ex": "Hỏi nơi diễn ra cuộc hội thoại là câu hỏi chung, thường nghe được ở đầu bài."}, {"q": "Đáp án của câu \"What will the woman probably do next?\" thường nằm ở đâu?", "opts": ["Trong phần hướng dẫn", "Cuối bài", "Giữa bài", "Đầu bài"], "a": 1, "ex": "Việc sẽ làm tiếp thường được nói ở cuối bài, với các mẫu I'll... / Let me... / I'm going to..."}, {"q": "Bài nghe: \"I'll email you the schedule tonight.\" Đáp án nào là paraphrase đúng?", "opts": ["Send some information", "Print a schedule", "Visit an office", "Call a manager"], "a": 0, "ex": "\"Email you the schedule\" = gửi thông tin. \"Print a schedule\" lặp từ schedule nhưng sai hành động (in chứ không phải gửi)."}, {"q": "Bài nghe: \"Our flight has been pushed back two hours.\" Điều gì xảy ra với chuyến bay?", "opts": ["It has been canceled.", "It is fully booked.", "It has been delayed.", "It will leave early."], "a": 2, "ex": "push back = lùi lại, hoãn → chuyến bay bị trễ (delayed), không phải bị hủy."}, {"q": "Trong câu hỏi \"What problem does the man mention?\", nên gạch những từ khóa nào?", "opts": ["What, does", "problem, man", "the, What", "does, mention"], "a": 1, "ex": "Từ khóa là nội dung cần nghe (problem = vấn đề) và người nói (man). Các từ còn lại không giúp định hướng khi nghe."}, {"q": "Bài nghe: \"We're really short-staffed this week.\" Đáp án nào cùng nghĩa?", "opts": ["Some employees are too tall.", "The week is very short.", "The staff room is too small.", "There are not enough employees."], "a": 3, "ex": "short-staffed = thiếu nhân viên. Các đáp án khác lặp từ short / staff / week nhưng sai nghĩa."}, {"q": "Bài nói: \"Thank you for calling Green Leaf Dental Clinic. Our office is now closed...\" Người nói làm việc ở đâu?", "opts": ["At a flower shop", "At a hotel", "At a dental clinic", "At a bank"], "a": 2, "ex": "\"Dental Clinic\" = phòng khám nha khoa. \"Green Leaf\" chỉ là tên, không liên quan đến cửa hàng hoa."}, {"q": "Bạn lỡ không nghe được câu trả lời cho câu 2 của một đoạn. Nên làm gì?", "opts": ["Chọn đoán một đáp án rồi tập trung vào câu tiếp theo", "Bỏ cả câu 3 để quay lại câu 2", "Dừng nghe để đọc lại câu 2", "Bỏ trống và cố nhớ lại đến hết bài"], "a": 0, "ex": "Đoạn nghe không phát lại. Đoán nhanh và đi tiếp giúp bạn không mất thêm các câu sau."}]}, {"id": "nghe-so-ngay-gio-gia", "group": "Nghe", "title": "Nghe số, ngày tháng, giờ, giá tiền", "level": 1, "mins": 10, "why": "Part 3–4 rất hay hỏi giờ, ngày, giá và số lượng; Part 2 hay có câu When / How much. Nghe nhầm thirteen với thirty là mất điểm dù hiểu cả bài.", "sections": [{"h": "-teen hay -ty?", "html": "<table><tr><th>-teen (13–19)</th><th>-ty (30–90)</th><th>Cách phân biệt</th></tr><tr><td>thir<b>TEEN</b> (13)</td><td><b>THIR</b>ty (30)</td><td rowspan=\"3\">-teen: nhấn âm <b>cuối</b>, âm \"teen\" dài và rõ chữ t<br>-ty: nhấn âm <b>đầu</b>, đuôi \"ty\" ngắn, nghe gần như \"đi\"</td></tr><tr><td>four<b>TEEN</b> (14)</td><td><b>FOR</b>ty (40)</td></tr><tr><td>fif<b>TEEN</b> (15)</td><td><b>FIF</b>ty (50)</td></tr></table><div class=\"note\">Khi đứng trước danh từ (fifteen people), trọng âm của -teen có thể dịch lên đầu. Lúc đó hãy dựa vào độ dài: \"teen\" vẫn dài hơn \"ty\".</div>"}, {"h": "Đọc năm và ngày tháng", "html": "<table><tr><th>Viết</th><th>Đọc</th></tr><tr><td>1998</td><td><span class=\"en\">nineteen ninety-eight</span></td></tr><tr><td>2005</td><td><span class=\"en\">two thousand five</span></td></tr><tr><td>2026</td><td><span class=\"en\">twenty twenty-six</span> hoặc <span class=\"en\">two thousand twenty-six</span></td></tr><tr><td>March 3</td><td><span class=\"en\">March third</span> / <span class=\"en\">the third of March</span></td></tr><tr><td>May 21</td><td><span class=\"en\">May twenty-first</span></td></tr></table><p>Ngày dùng <b>số thứ tự</b>: first, second, third, fourth... twenty-first, thirty-first.</p>"}, {"h": "Đọc giờ", "html": "<table><tr><th>Giờ</th><th>Cách 1</th><th>Cách 2</th></tr><tr><td>8:15</td><td><span class=\"en\">eight fifteen</span></td><td><span class=\"en\">a quarter past eight</span></td></tr><tr><td>6:30</td><td><span class=\"en\">six thirty</span></td><td><span class=\"en\">half past six</span></td></tr><tr><td>7:45</td><td><span class=\"en\">seven forty-five</span></td><td><span class=\"en\">a quarter to eight</span></td></tr><tr><td>9:50</td><td><span class=\"en\">nine fifty</span></td><td><span class=\"en\">ten to ten</span></td></tr></table><p><b>past</b> = hơn (đã qua giờ đó), <b>to</b> = kém (còn ... phút nữa đến giờ đó). <b>a quarter</b> = 15 phút.</p>"}, {"h": "Giá tiền và số điện thoại", "html": "<ul><li>$12.99 → <span class=\"en\">twelve ninety-nine</span> hoặc <span class=\"en\">twelve dollars and ninety-nine cents</span></li><li>$1,500 → <span class=\"en\">one thousand five hundred dollars</span> hoặc <span class=\"en\">fifteen hundred dollars</span></li><li>Số 0 trong số điện thoại, số phòng thường đọc là <span class=\"en\">oh</span>: room 405 → <span class=\"en\">four oh five</span></li><li>Trong số điện thoại, hai số giống nhau liền nhau có thể đọc gộp: 77 → <span class=\"en\">double seven</span></li></ul>"}], "tips": ["Viết số ra nháp ngay khi nghe, đừng cố nhớ trong đầu.", "Nghe cả những từ thay đổi con số: \"It was 30, but now it's 40\" → con số mới mới là đáp án.", "Tự đọc to giờ và giá tiền mỗi ngày (giờ trên điện thoại, giá trong siêu thị) để quen tai."], "mistakes": ["Nhầm \"a quarter to eight\" là 8:15 → \"to\" là kém, nên là 7:45.", "Nghe -teen và -ty như nhau → chú ý trọng âm và độ dài âm cuối.", "Chọn con số được nhắc đầu tiên → bài nghe hay đổi số (giá cũ / giá mới, giờ cũ / giờ mới)."], "quiz": [{"q": "\"a quarter to eight\" là mấy giờ?", "opts": ["7:45", "8:15", "8:45", "7:15"], "a": 0, "ex": "to = kém. Tám giờ kém mười lăm = 7:45. \"a quarter past eight\" mới là 8:15."}, {"q": "\"half past six\" là mấy giờ?", "opts": ["6:50", "5:30", "6:30", "6:15"], "a": 2, "ex": "half = một nửa (30 phút), past = hơn → sáu giờ rưỡi = 6:30."}, {"q": "\"twenty twenty-six\" là năm nào?", "opts": ["2006", "2026", "2260", "2020"], "a": 1, "ex": "Năm có 4 chữ số thường đọc theo cặp: twenty (20) + twenty-six (26) = 2026."}, {"q": "Từ nào khi đọc riêng được nhấn âm ở CUỐI?", "opts": ["fifty", "forty", "ninety", "fourteen"], "a": 3, "ex": "Các số -teen nhấn âm cuối (four-TEEN). Các số -ty nhấn âm đầu (FOR-ty, FIF-ty, NINE-ty)."}, {"q": "Giá \"$15.50\" thường được đọc là gì?", "opts": ["one five five oh", "fifteen five", "fifteen fifty", "fifty fifteen"], "a": 2, "ex": "Đọc phần đô la trước rồi phần xu: fifteen (15) fifty (50)."}, {"q": "\"ten to nine\" là mấy giờ?", "opts": ["8:50", "9:50", "10:09", "9:10"], "a": 0, "ex": "Chín giờ kém mười = 8:50. Còn 10 phút nữa mới đến 9 giờ."}, {"q": "\"nineteen eighty-five\" là năm nào?", "opts": ["9185", "1958", "1895", "1985"], "a": 3, "ex": "nineteen (19) + eighty-five (85) = 1985."}, {"q": "Bài nghe: \"The tour was going to start at 9:30, but now it starts at 10:00.\" Tour bắt đầu lúc mấy giờ?", "opts": ["9:30", "10:00", "10:30", "9:00"], "a": 1, "ex": "Giờ cũ là 9:30 nhưng đã đổi; \"but now\" báo hiệu thông tin mới → 10:00."}]}, {"id": "part-5-6-cach-lam-nhanh", "group": "Đọc", "title": "Part 5–6 – Cách làm nhanh", "level": 2, "mins": 14, "why": "Part 5–6 có 46 câu. Làm nhanh và chắc ở đây giúp bạn còn đủ thời gian cho 54 câu Part 7, nơi nhiều bạn bị hết giờ.", "sections": [{"h": "Bước 1: nhìn đáp án trước để biết dạng câu", "html": "<table><tr><th>Đáp án trông như thế nào</th><th>Dạng câu</th><th>Cách làm</th></tr><tr><td>Cùng một gốc từ: decide / decision / decisive / decisively</td><td><b>Từ loại</b></td><td>Chỉ cần nhìn từ ngay trước và ngay sau chỗ trống, không cần dịch cả câu</td></tr><tr><td>Cùng một động từ khác thì / dạng: send / sent / is sending / will send</td><td><b>Ngữ pháp</b> (thì, chủ động / bị động)</td><td>Tìm dấu hiệu thời gian và chủ ngữ</td></tr><tr><td>Giới từ, liên từ, đại từ: although / because / despite</td><td><b>Ngữ pháp</b> (từ nối)</td><td>Xem sau chỗ trống là mệnh đề hay danh từ, và quan hệ ý hai vế</td></tr><tr><td>Bốn từ khác nghĩa, cùng từ loại: reserve / remind / reply / repair</td><td><b>Từ vựng</b></td><td>Phải hiểu nghĩa câu, chú ý cụm từ đi kèm</td></tr></table>"}, {"h": "Dấu hiệu từ loại hay gặp", "html": "<table><tr><th>Vị trí chỗ trống</th><th>Cần</th><th>Ví dụ</th></tr><tr><td>Sau a / an / the / tính từ sở hữu (his, our...)</td><td>Danh từ</td><td><span class=\"en\">our <b>decision</b></span></td></tr><tr><td>Trước danh từ</td><td>Tính từ</td><td><span class=\"en\">a <b>successful</b> event</span></td></tr><tr><td>Sau động từ to be / become / seem</td><td>Tính từ</td><td><span class=\"en\">The plan is <b>flexible</b>.</span></td></tr><tr><td>Bổ nghĩa cho động từ / tính từ</td><td>Trạng từ (thường đuôi -ly)</td><td><span class=\"en\">check <b>carefully</b>, <b>highly</b> skilled</span></td></tr></table>"}, {"h": "Part 6: điền câu vào đoạn văn", "html": "<p>Mỗi đoạn Part 6 có 4 chỗ trống, trong đó <b>1 chỗ phải chèn cả một câu</b>.</p><ol><li>Đọc câu <b>ngay trước</b> và <b>ngay sau</b> chỗ trống.</li><li>Chú ý từ nối (However, Also, As a result) và đại từ (it, this, these, they) trong các đáp án: chúng phải chỉ đến thứ đã nhắc trước đó.</li><li>Loại câu đúng ngữ pháp nhưng lạc đề hoặc mâu thuẫn với đoạn văn.</li></ol><div class=\"ex\"><span class=\"en\">Your package was shipped this morning. ____ You can track it on our website.</span><br>✓ <span class=\"en\">It should arrive within three days.</span><br><span class=\"vi\">\"It\" chỉ \"package\"; câu nói về thời gian giao, nối tốt với câu theo dõi đơn hàng.</span></div>"}], "tips": ["Câu từ loại làm trong 10–15 giây; để dành thời gian cho câu từ vựng.", "Part 6 cũng có câu thì động từ phụ thuộc cả đoạn: đọc câu xung quanh để biết sự việc đã xảy ra hay sắp xảy ra.", "Không chắc câu nào thì chọn tạm, đánh dấu, làm hết rồi mới quay lại."], "mistakes": ["Dịch cả câu cho câu hỏi từ loại → chỉ cần nhìn vị trí chỗ trống.", "Dùng despite / because of trước một mệnh đề → hai từ này đi với danh từ; trước mệnh đề dùng although / because.", "Ở Part 6 chỉ đọc mỗi câu có chỗ trống → phải đọc ngữ cảnh trước và sau."], "quiz": [{"q": "The manager made a final ____ about the new office.", "opts": ["decide", "decision", "decisively", "decisive"], "a": 1, "ex": "Sau tính từ \"final\" và mạo từ \"a\" cần một danh từ → decision (quyết định)."}, {"q": "Please read the instructions ____ before using the machine.", "opts": ["care", "careful", "cared", "carefully"], "a": 3, "ex": "Cần trạng từ bổ nghĩa cho động từ \"read\" → carefully (một cách cẩn thận)."}, {"q": "____ it was raining, the outdoor event started on time.", "opts": ["Because", "So", "Although", "Despite"], "a": 2, "ex": "Hai vế trái ngược (mưa nhưng vẫn bắt đầu đúng giờ) và sau chỗ trống là mệnh đề → Although. Despite phải đi với danh từ; Because sai nghĩa."}, {"q": "Đáp án: (A) report (B) reported (C) reporting (D) reporter. Đây là dạng câu gì?", "opts": ["Từ loại / dạng từ", "Liên từ", "Giới từ", "Từ vựng"], "a": 0, "ex": "Bốn đáp án cùng gốc \"report\" ở các dạng khác nhau → dạng câu từ loại, nhìn vị trí chỗ trống là làm được."}, {"q": "The new software is very ____ and easy to use.", "opts": ["effect", "effects", "effectively", "effective"], "a": 3, "ex": "Sau \"is very\" cần tính từ, và \"and easy\" cũng là tính từ → effective (hiệu quả)."}, {"q": "The store opens ____ 9 A.M. every day.", "opts": ["during", "at", "on", "in"], "a": 1, "ex": "Trước giờ cụ thể dùng \"at\". \"in\" dùng cho tháng / năm, \"on\" dùng cho ngày / thứ."}, {"q": "Thank you for ordering from Bright Home. Your package was shipped this morning. ____ You can track it on our website using the code in this email.", "opts": ["It should arrive within three days.", "We are hiring new drivers.", "Our first store opened in 2010.", "Please choose the items you want to buy."], "a": 0, "ex": "Đoạn văn nói về đơn hàng đã gửi đi. Câu về thời gian giao hàng nối tự nhiên với câu theo dõi đơn hàng; các câu còn lại lạc đề hoặc sai thứ tự (đã mua rồi)."}, {"q": "The report must be submitted ____ Friday.", "opts": ["for", "until", "by", "since"], "a": 2, "ex": "by + thời điểm = trước hạn chót. \"until\" dùng cho hành động kéo dài, không dùng với submit (nộp, xảy ra một lần)."}]}, {"id": "part-7-doc-hieu", "group": "Đọc", "title": "Part 7 – Đọc lướt, đọc tìm và các dạng câu hỏi", "level": 2, "mins": 15, "why": "Part 7 có 54 câu, chiếm hơn một nửa phần Đọc. Không ai đọc kịp từng chữ; bạn cần biết đọc lướt, đọc tìm và nhận ra dạng câu hỏi để biết phải tìm gì.", "sections": [{"h": "Skim và scan", "html": "<table><tr><th>Cách đọc</th><th>Mục đích</th><th>Khi nào dùng</th></tr><tr><td><b>Skim</b> (đọc lướt)</td><td>Nắm ý chính: bài nói về gì, ai viết cho ai</td><td>Câu hỏi mục đích, chủ đề</td></tr><tr><td><b>Scan</b> (đọc tìm)</td><td>Tìm nhanh một thông tin cụ thể: tên, số, ngày, giờ</td><td>Câu hỏi chi tiết</td></tr></table><p>Cách làm: <b>đọc câu hỏi trước</b> → gạch từ khóa → quay lại bài tìm chỗ chứa từ khóa (hoặc từ đồng nghĩa) → đọc kỹ 1–2 câu quanh đó.</p>"}, {"h": "Các dạng câu hỏi thường gặp", "html": "<table><tr><th>Dạng</th><th>Câu hỏi mẫu</th><th>Cách làm</th></tr><tr><td>Mục đích / chủ đề</td><td><span class=\"en\">What is the purpose of the e-mail?</span></td><td>Đọc tiêu đề và đoạn đầu</td></tr><tr><td>Chi tiết</td><td><span class=\"en\">When will the repairs begin?</span></td><td>Scan tìm từ khóa</td></tr><tr><td>NOT true</td><td><span class=\"en\">What is NOT mentioned about the store?</span></td><td>Tìm 3 đáp án CÓ trong bài, loại dần</td></tr><tr><td>Suy luận</td><td><span class=\"en\">What is suggested / implied / most likely...?</span></td><td>Đáp án không viết thẳng nhưng phải có căn cứ trong bài</td></tr><tr><td>Từ đồng nghĩa</td><td><span class=\"en\">The word \"cover\" in paragraph 2 is closest in meaning to</span></td><td>Đọc cả câu chứa từ, thay thử từng đáp án vào</td></tr><tr><td>Chèn câu</td><td><span class=\"en\">In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?</span></td><td>Tìm từ nối, đại từ trong câu cần chèn</td></tr></table>"}, {"h": "Ví dụ ngắn", "html": "<div class=\"ex\"><span class=\"en\"><i>Notice to all tenants: The elevator in Building C will be closed for repairs from June 3 to June 5. During this time, please use the stairs or the elevator in Building D. We apologize for any inconvenience. – Sunview Apartments Management</i></span></div><ul><li>Mục đích → thông báo thang máy tạm đóng cửa (<span class=\"vi\">announce a temporary closure</span>).</li><li>Chi tiết → cư dân được yêu cầu đi thang bộ hoặc thang máy tòa D.</li><li>NOT mentioned → bài không nói chi phí sửa chữa.</li></ul><div class=\"note\">Câu hỏi từ đồng nghĩa: nghĩa phụ thuộc vào câu. <span class=\"en\">The hotel will cover the cost of your taxi.</span> → cover = <b>pay for</b> (chi trả), không phải \"che phủ\".</div>"}], "tips": ["Bắt đầu Part 7 từ các bài ngắn (tin nhắn, thông báo) vì nhanh lấy điểm.", "Câu hỏi thường đi theo thứ tự thông tin trong bài, trừ câu hỏi mục đích và NOT true.", "Đáp án đúng thường là paraphrase của câu trong bài, hiếm khi chép nguyên văn."], "mistakes": ["Đọc kỹ từng chữ từ đầu đến cuối rồi mới xem câu hỏi → đọc câu hỏi trước rồi mới tìm.", "Câu suy luận chọn đáp án theo hiểu biết riêng → phải có căn cứ trong bài.", "Câu đồng nghĩa chọn nghĩa phổ biến nhất của từ → phải dựa vào ngữ cảnh câu."], "quiz": [{"q": "Đọc thông báo: \"Notice to all tenants: The elevator in Building C will be closed for repairs from June 3 to June 5. During this time, please use the stairs or the elevator in Building D. We apologize for any inconvenience. – Sunview Apartments Management\" — What is the purpose of the notice?", "opts": ["To ask tenants for payment", "To introduce new tenants", "To announce a temporary closure", "To advertise an apartment"], "a": 2, "ex": "Thông báo nói thang máy tòa C đóng cửa để sửa trong vài ngày → thông báo việc tạm đóng cửa."}, {"q": "Đọc thông báo: \"Notice to all tenants: The elevator in Building C will be closed for repairs from June 3 to June 5. During this time, please use the stairs or the elevator in Building D. We apologize for any inconvenience. – Sunview Apartments Management\" — What are tenants asked to do?", "opts": ["Use the stairs or another elevator", "Pay for the repairs", "Move to Building D", "Call the management office"], "a": 0, "ex": "Bài viết: \"please use the stairs or the elevator in Building D\" → dùng thang bộ hoặc thang máy khác. Bài không yêu cầu chuyển sang ở tòa D."}, {"q": "Đọc thông báo: \"Notice to all tenants: The elevator in Building C will be closed for repairs from June 3 to June 5. During this time, please use the stairs or the elevator in Building D. We apologize for any inconvenience. – Sunview Apartments Management\" — What is NOT mentioned in the notice?", "opts": ["Which elevator will be closed", "Another option for tenants", "The dates of the repairs", "The cost of the repairs"], "a": 3, "ex": "Bài có ngày (June 3–5), có tên thang máy (Building C), có lựa chọn khác (thang bộ, tòa D), nhưng không nói chi phí."}, {"q": "\"The hotel will cover the cost of your taxi.\" The word \"cover\" is closest in meaning to", "opts": ["report", "pay for", "hide", "protect"], "a": 1, "ex": "Trong câu này, cover the cost = chi trả chi phí → pay for. \"hide\" (che giấu) là nghĩa khác không hợp ngữ cảnh."}, {"q": "Câu hỏi \"What time does the workshop start?\" nên dùng cách đọc nào?", "opts": ["Scan (đọc tìm)", "Skim (đọc lướt ý chính)", "Chỉ đọc đoạn cuối", "Đọc kỹ từng chữ từ đầu bài"], "a": 0, "ex": "Đây là câu hỏi chi tiết (giờ cụ thể) → scan tìm con số chỉ giờ trong bài."}, {"q": "Câu hỏi có các từ \"most likely\", \"suggested\", \"implied\" thường thuộc dạng nào?", "opts": ["Chèn câu", "NOT true", "Suy luận", "Từ đồng nghĩa"], "a": 2, "ex": "Những từ này cho biết đáp án không viết thẳng trong bài, bạn phải suy ra từ thông tin có sẵn."}, {"q": "Câu cần chèn: \"However, the price will increase next month.\" Câu này nên đứng ngay sau câu nào?", "opts": ["Thank you for joining us.", "Our basic plan currently costs $10 per month.", "Our office is located on Main Street.", "Please contact us if you have any questions."], "a": 1, "ex": "\"However\" báo hiệu ý trái ngược, và \"the price\" phải nói về một giá đã nhắc trước đó → đứng sau câu nói giá hiện tại là $10."}, {"q": "Với câu hỏi NOT true, cách làm hiệu quả nhất là gì?", "opts": ["Chọn đáp án dài nhất", "Chỉ đọc tiêu đề", "Chọn đáp án có từ giống trong bài nhất", "Tìm trong bài 3 đáp án có được nhắc, đáp án còn lại là đáp án đúng"], "a": 3, "ex": "Câu NOT true hỏi điều KHÔNG có hoặc sai. Loại dần 3 đáp án đúng với bài là cách chắc chắn nhất."}]}, {"id": "bo-cuc-email-thong-bao-quang-cao", "group": "Đọc", "title": "Bố cục email, thư, thông báo, quảng cáo", "level": 1, "mins": 10, "why": "Phần lớn bài đọc Part 6 và Part 7 là email, thư, thông báo, quảng cáo. Biết thông tin nằm ở đâu giúp bạn tìm đáp án nhanh mà không cần đọc hết bài.", "sections": [{"h": "Email và thư", "html": "<table><tr><th>Phần</th><th>Cho biết gì</th><th>Câu hỏi liên quan</th></tr><tr><td>From / To</td><td>Người gửi, người nhận</td><td><span class=\"en\">Who most likely is Mr. Vo?</span></td></tr><tr><td>Date</td><td>Ngày gửi</td><td>Tính hạn chót, \"next Friday\" là ngày nào</td></tr><tr><td>Subject</td><td>Chủ đề chính</td><td><span class=\"en\">Why was the e-mail sent?</span></td></tr><tr><td>Đoạn đầu</td><td>Lý do viết: <span class=\"en\">I am writing to...</span></td><td>Mục đích</td></tr><tr><td>Đoạn giữa</td><td>Chi tiết: thời gian, giá, thay đổi</td><td>Câu hỏi chi tiết</td></tr><tr><td>Đoạn cuối</td><td>Yêu cầu: <span class=\"en\">Please...</span>, <span class=\"en\">I would appreciate it if...</span></td><td><span class=\"en\">What is the reader asked to do?</span></td></tr><tr><td>Chữ ký</td><td>Tên, chức vụ, công ty</td><td>Người gửi làm nghề gì, ở đâu</td></tr></table>"}, {"h": "Thông báo và memo", "html": "<ul><li><b>Tiêu đề</b> → chủ đề, ví dụ <span class=\"en\">Office Closure Notice</span>.</li><li><b>Đối tượng</b> → <span class=\"en\">To: All staff</span> / <span class=\"en\">Attention: Residents</span> (<span class=\"vi\">gửi ai</span>).</li><li><b>Nội dung</b> → việc gì thay đổi, từ khi nào, lý do.</li><li><b>Cuối bài</b> → cần làm gì, liên hệ ai.</li></ul><p><b>Memo</b> là thông báo nội bộ gửi nhân viên trong một công ty.</p>"}, {"h": "Quảng cáo", "html": "<ul><li><b>Tên sản phẩm / dịch vụ</b> và lợi ích chính (thường in to ở đầu).</li><li><b>Ưu đãi</b>: <span class=\"en\">20% off</span>, <span class=\"en\">free delivery</span>, <span class=\"en\">buy one, get one free</span>.</li><li><b>Thời hạn</b>: <span class=\"en\">valid until May 31</span>, <span class=\"en\">this weekend only</span>.</li><li><b>Điều kiện</b>: dấu * dẫn tới dòng chữ nhỏ cuối bài, ví dụ <span class=\"en\">*Online orders only</span>.</li><li><b>Cách liên hệ</b>: website, số điện thoại, địa chỉ.</li></ul><div class=\"note\">Câu hỏi về điều kiện ưu đãi rất hay nằm ở dòng chữ nhỏ có dấu *.</div>"}], "tips": ["Luôn đọc tiêu đề, người gửi và ngày trước khi đọc nội dung.", "Thấy câu hỏi \"What is ... asked to do?\" thì nhảy ngay xuống đoạn cuối.", "Ghi nhớ ngày gửi để tính các mốc như \"tomorrow\", \"next Monday\" trong bài."], "mistakes": ["Bỏ qua phần chữ ký → chức vụ người gửi thường là đáp án của câu hỏi \"Who is...\".", "Bỏ qua dòng chữ nhỏ có dấu * trong quảng cáo → điều kiện ưu đãi nằm ở đó.", "Nhầm người gửi với người nhận → From là người gửi, To là người nhận."], "quiz": [{"q": "Muốn biết mục đích của email, nên đọc phần nào trước?", "opts": ["Dòng chữ nhỏ cuối thư", "Chữ ký", "Ngày gửi", "Subject và đoạn đầu"], "a": 3, "ex": "Tiêu đề (Subject) và câu \"I am writing to...\" ở đoạn đầu cho biết lý do viết email."}, {"q": "Câu hỏi \"Who most likely is the sender?\" thường tìm thông tin ở đâu?", "opts": ["Lời chào Dear...", "Phần chữ ký (tên, chức vụ, công ty)", "Ngày gửi", "Tiêu đề"], "a": 1, "ex": "Chữ ký cuối thư ghi chức vụ và công ty của người gửi. Lời chào Dear... là tên người nhận."}, {"q": "Phần cuối email thường chứa nội dung gì?", "opts": ["Yêu cầu hoặc việc người đọc cần làm", "Tiêu đề email", "Ngày gửi email", "Lý do viết email"], "a": 0, "ex": "Đoạn cuối hay có Please... / I would appreciate it if... → việc người đọc cần làm. Lý do viết nằm ở đoạn đầu."}, {"q": "Trong quảng cáo, dấu * thường dẫn tới thông tin gì?", "opts": ["Lời cảm ơn khách hàng", "Tên sản phẩm", "Điều kiện áp dụng ưu đãi", "Tên công ty"], "a": 2, "ex": "Dấu * dẫn tới dòng chữ nhỏ ghi điều kiện, ví dụ \"*Online orders only\"."}, {"q": "\"Memo\" là loại văn bản gì?", "opts": ["Quảng cáo sản phẩm", "Thông báo nội bộ gửi nhân viên trong công ty", "Hóa đơn mua hàng", "Thư xin việc"], "a": 1, "ex": "Memo (memorandum) là văn bản nội bộ trong công ty, thường bắt đầu bằng To / From / Date / Subject."}, {"q": "Email có Subject: \"Change to Friday's training session\". Mục đích email là gì?", "opts": ["Mời đi phỏng vấn", "Khiếu nại sản phẩm", "Đặt mua hàng", "Thông báo thay đổi về buổi đào tạo"], "a": 3, "ex": "change = thay đổi, training session = buổi đào tạo → email thông báo buổi đào tạo thứ Sáu có thay đổi."}, {"q": "Câu \"Please reply by October 30.\" cho biết điều gì?", "opts": ["Ngày email được gửi", "Ngày bắt đầu sự kiện", "Hạn chót người đọc phải trả lời", "Ngày hết hạn ưu đãi"], "a": 2, "ex": "reply by + ngày = trả lời trước ngày đó → đây là hạn chót, không phải ngày gửi."}, {"q": "Câu \"I am writing to inform you that...\" thường nằm ở đâu trong thư?", "opts": ["Đầu thư, để nêu mục đích", "Trong chữ ký", "Cuối thư, để đưa yêu cầu", "Trong tiêu đề"], "a": 0, "ex": "\"I am writing to...\" = Tôi viết thư này để... → câu mở đầu nêu mục đích viết."}]}, {"id": "tu-vung-van-phong", "group": "Từ vựng", "title": "Từ vựng: Văn phòng và công việc hằng ngày", "level": 1, "mins": 12, "why": "Chủ đề văn phòng xuất hiện ở hầu hết các Part: tranh văn phòng ở Part 1, hội thoại đồng nghiệp ở Part 3, email nội bộ ở Part 7.", "sections": [{"h": "Từ vựng cốt lõi (phần 1)", "html": "<table><tr><th>Từ</th><th>Loại từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td><b>colleague</b></td><td>n</td><td>đồng nghiệp</td><td><span class=\"en\">My colleague helped me fix the printer.</span><br><span class=\"vi\">Đồng nghiệp đã giúp mình sửa máy in.</span></td></tr><tr><td><b>supervisor</b></td><td>n</td><td>người giám sát, cấp trên</td><td><span class=\"en\">Ask your supervisor before you leave early.</span><br><span class=\"vi\">Hãy hỏi cấp trên trước khi về sớm.</span></td></tr><tr><td><b>department</b></td><td>n</td><td>phòng, ban</td><td><span class=\"en\">She works in the marketing department.</span><br><span class=\"vi\">Cô ấy làm ở phòng marketing.</span></td></tr><tr><td><b>deadline</b></td><td>n</td><td>hạn chót</td><td><span class=\"en\">The deadline for the report is Friday.</span><br><span class=\"vi\">Hạn chót nộp báo cáo là thứ Sáu.</span></td></tr><tr><td><b>assignment</b></td><td>n</td><td>nhiệm vụ được giao</td><td><span class=\"en\">Each new employee gets a small assignment.</span><br><span class=\"vi\">Mỗi nhân viên mới nhận một nhiệm vụ nhỏ.</span></td></tr><tr><td><b>submit</b></td><td>v</td><td>nộp</td><td><span class=\"en\">Please submit your timesheet by noon.</span><br><span class=\"vi\">Vui lòng nộp bảng chấm công trước buổi trưa.</span></td></tr><tr><td><b>approve</b></td><td>v</td><td>phê duyệt</td><td><span class=\"en\">The director approved our plan.</span><br><span class=\"vi\">Giám đốc đã phê duyệt kế hoạch của chúng tôi.</span></td></tr><tr><td><b>attach</b></td><td>v</td><td>đính kèm</td><td><span class=\"en\">I attached the photos to this e-mail.</span><br><span class=\"vi\">Mình đã đính kèm ảnh vào email này.</span></td></tr><tr><td><b>forward</b></td><td>v</td><td>chuyển tiếp</td><td><span class=\"en\">Could you forward this message to Mr. Nam?</span><br><span class=\"vi\">Bạn chuyển tiếp tin nhắn này cho anh Nam được không?</span></td></tr><tr><td><b>file</b></td><td>v / n</td><td>sắp xếp hồ sơ / tập tin, hồ sơ</td><td><span class=\"en\">He filed the invoices in the cabinet.</span><br><span class=\"vi\">Anh ấy cất các hóa đơn vào tủ hồ sơ.</span></td></tr></table>"}, {"h": "Từ vựng cốt lõi (phần 2)", "html": "<table><tr><th>Từ</th><th>Loại từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td><b>cabinet</b></td><td>n</td><td>tủ (đựng hồ sơ)</td><td><span class=\"en\">The keys are in the top drawer of the cabinet.</span><br><span class=\"vi\">Chìa khóa ở ngăn trên cùng của tủ.</span></td></tr><tr><td><b>photocopier</b></td><td>n</td><td>máy photocopy</td><td><span class=\"en\">The photocopier on the second floor is out of paper.</span><br><span class=\"vi\">Máy photocopy ở tầng hai hết giấy.</span></td></tr><tr><td><b>supplies</b></td><td>n</td><td>đồ dùng, vật tư</td><td><span class=\"en\">We need to order more office supplies.</span><br><span class=\"vi\">Chúng ta cần đặt thêm văn phòng phẩm.</span></td></tr><tr><td><b>extension</b></td><td>n</td><td>số máy lẻ (điện thoại)</td><td><span class=\"en\">You can call me at extension 305.</span><br><span class=\"vi\">Bạn có thể gọi mình ở số máy lẻ 305.</span></td></tr><tr><td><b>memo</b></td><td>n</td><td>thông báo nội bộ</td><td><span class=\"en\">The memo says the office will close early today.</span><br><span class=\"vi\">Thông báo nội bộ nói hôm nay văn phòng đóng cửa sớm.</span></td></tr><tr><td><b>shift</b></td><td>n</td><td>ca làm việc</td><td><span class=\"en\">Linh works the morning shift this week.</span><br><span class=\"vi\">Tuần này Linh làm ca sáng.</span></td></tr><tr><td><b>repair</b></td><td>v / n</td><td>sửa chữa</td><td><span class=\"en\">A technician will repair the air conditioner.</span><br><span class=\"vi\">Một kỹ thuật viên sẽ sửa máy lạnh.</span></td></tr><tr><td><b>urgent</b></td><td>adj</td><td>khẩn cấp, gấp</td><td><span class=\"en\">This is an urgent request, so please reply today.</span><br><span class=\"vi\">Đây là yêu cầu gấp, vui lòng trả lời trong hôm nay.</span></td></tr><tr><td><b>responsible (for)</b></td><td>adj</td><td>chịu trách nhiệm (về)</td><td><span class=\"en\">Mr. Long is responsible for training new staff.</span><br><span class=\"vi\">Anh Long chịu trách nhiệm đào tạo nhân viên mới.</span></td></tr></table>"}, {"h": "Cụm từ hay đi cùng", "html": "<table><tr><th>Cụm từ</th><th>Nghĩa</th></tr><tr><td>meet a deadline</td><td>kịp hạn chót</td></tr><tr><td>office supplies</td><td>văn phòng phẩm</td></tr><tr><td>work overtime</td><td>làm thêm giờ</td></tr><tr><td>be out of paper / ink</td><td>hết giấy / mực</td></tr><tr><td>take a day off</td><td>nghỉ một ngày</td></tr></table>"}], "tips": ["Học từ theo cụm (submit a report, approve a request) thay vì học từ đơn lẻ.", "Mỗi ngày đọc lại bảng và tự đặt một câu với 3 từ bất kỳ."], "mistakes": ["Dùng \"file\" chỉ với nghĩa tập tin máy tính → trong TOEIC, \"file\" còn là động từ \"sắp xếp hồ sơ\".", "Nói \"responsible to do something\" → đúng là \"responsible for + V-ing / danh từ\".", "Nhầm \"extension\" chỉ là \"gia hạn\" → trong số điện thoại văn phòng, extension là số máy lẻ."], "quiz": [{"q": "Please ____ the report to me before 5 P.M.", "opts": ["submit", "approve", "attach", "repair"], "a": 0, "ex": "submit something to someone = nộp cái gì cho ai. \"attach the report to me\" và \"approve the report to me\" không đúng cách dùng."}, {"q": "\"supervisor\" nghĩa là gì?", "opts": ["khách hàng", "đồng nghiệp", "người giám sát, cấp trên", "nhà cung cấp"], "a": 2, "ex": "supervisor = người giám sát, cấp trên trực tiếp. Đồng nghiệp là colleague."}, {"q": "We've run out of paper. I'll order more office ____.", "opts": ["shifts", "supplies", "deadlines", "departments"], "a": 1, "ex": "office supplies = văn phòng phẩm (giấy, bút...). Hết giấy thì đặt thêm văn phòng phẩm."}, {"q": "\"urgent\" nghĩa là gì?", "opts": ["miễn phí", "rõ ràng", "chậm trễ", "khẩn cấp, gấp"], "a": 3, "ex": "urgent = khẩn cấp, cần làm ngay."}, {"q": "You can reach me by phone at ____ 214.", "opts": ["memo", "colleague", "extension", "cabinet"], "a": 2, "ex": "extension + số = số máy lẻ trong văn phòng."}, {"q": "I have ____ the price list to this e-mail.", "opts": ["attached", "repaired", "approved", "scheduled"], "a": 0, "ex": "attach something to an e-mail = đính kèm vào email."}, {"q": "\"approve\" nghĩa là gì?", "opts": ["đính kèm", "chuyển tiếp", "sửa chữa", "phê duyệt"], "a": 3, "ex": "approve = phê duyệt, đồng ý. Sửa chữa là repair, đính kèm là attach, chuyển tiếp là forward."}, {"q": "Lan works the night ____ at the factory.", "opts": ["extension", "shift", "supply", "deadline"], "a": 1, "ex": "the night shift = ca đêm."}]}, {"id": "tu-vung-tuyen-dung-nhan-su", "group": "Từ vựng", "title": "Từ vựng: Tuyển dụng và nhân sự", "level": 1, "mins": 12, "why": "Tin tuyển dụng và email mời phỏng vấn là bài đọc rất phổ biến ở Part 7; hội thoại về thăng chức, nghỉ hưu hay gặp ở Part 3–4.", "sections": [{"h": "Từ vựng cốt lõi (phần 1)", "html": "<table><tr><th>Từ</th><th>Loại từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td><b>job opening / vacancy</b></td><td>n</td><td>vị trí đang tuyển</td><td><span class=\"en\">There is a job opening in our Da Nang office.</span><br><span class=\"vi\">Văn phòng Đà Nẵng của chúng tôi đang có vị trí cần tuyển.</span></td></tr><tr><td><b>position</b></td><td>n</td><td>vị trí, chức vụ</td><td><span class=\"en\">She applied for the position of sales manager.</span><br><span class=\"vi\">Cô ấy ứng tuyển vị trí trưởng phòng kinh doanh.</span></td></tr><tr><td><b>apply (for)</b></td><td>v</td><td>ứng tuyển, nộp đơn</td><td><span class=\"en\">Five people applied for the job.</span><br><span class=\"vi\">Năm người đã nộp đơn cho công việc này.</span></td></tr><tr><td><b>applicant</b></td><td>n</td><td>người nộp đơn</td><td><span class=\"en\">All applicants must speak English.</span><br><span class=\"vi\">Tất cả người nộp đơn phải nói được tiếng Anh.</span></td></tr><tr><td><b>candidate</b></td><td>n</td><td>ứng viên</td><td><span class=\"en\">We will interview three candidates tomorrow.</span><br><span class=\"vi\">Ngày mai chúng tôi sẽ phỏng vấn ba ứng viên.</span></td></tr><tr><td><b>résumé</b></td><td>n</td><td>sơ yếu lý lịch, CV</td><td><span class=\"en\">Please attach your résumé to the form.</span><br><span class=\"vi\">Vui lòng đính kèm CV vào mẫu đơn.</span></td></tr><tr><td><b>interview</b></td><td>n / v</td><td>buổi phỏng vấn / phỏng vấn</td><td><span class=\"en\">The interview will take about thirty minutes.</span><br><span class=\"vi\">Buổi phỏng vấn kéo dài khoảng ba mươi phút.</span></td></tr><tr><td><b>qualified</b></td><td>adj</td><td>đủ năng lực, đủ trình độ</td><td><span class=\"en\">He is qualified to teach computer skills.</span><br><span class=\"vi\">Anh ấy đủ năng lực để dạy tin học.</span></td></tr><tr><td><b>requirement</b></td><td>n</td><td>yêu cầu</td><td><span class=\"en\">Two years of experience is a requirement.</span><br><span class=\"vi\">Hai năm kinh nghiệm là một yêu cầu.</span></td></tr><tr><td><b>experience</b></td><td>n</td><td>kinh nghiệm</td><td><span class=\"en\">Do you have experience in customer service?</span><br><span class=\"vi\">Bạn có kinh nghiệm chăm sóc khách hàng không?</span></td></tr></table>"}, {"h": "Từ vựng cốt lõi (phần 2)", "html": "<table><tr><th>Từ</th><th>Loại từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td><b>hire</b></td><td>v</td><td>thuê, tuyển</td><td><span class=\"en\">The hotel plans to hire ten new staff.</span><br><span class=\"vi\">Khách sạn dự định tuyển mười nhân viên mới.</span></td></tr><tr><td><b>recruit</b></td><td>v</td><td>tuyển dụng</td><td><span class=\"en\">The company recruits students every summer.</span><br><span class=\"vi\">Công ty tuyển sinh viên mỗi mùa hè.</span></td></tr><tr><td><b>salary</b></td><td>n</td><td>lương</td><td><span class=\"en\">The salary depends on your experience.</span><br><span class=\"vi\">Mức lương tùy vào kinh nghiệm của bạn.</span></td></tr><tr><td><b>benefits</b></td><td>n</td><td>phúc lợi (bảo hiểm, nghỉ phép...)</td><td><span class=\"en\">The job offers good benefits, such as health insurance.</span><br><span class=\"vi\">Công việc có phúc lợi tốt, như bảo hiểm y tế.</span></td></tr><tr><td><b>full-time / part-time</b></td><td>adj</td><td>toàn thời gian / bán thời gian</td><td><span class=\"en\">Mai has a part-time job at a bookstore.</span><br><span class=\"vi\">Mai làm bán thời gian ở một hiệu sách.</span></td></tr><tr><td><b>training</b></td><td>n</td><td>đào tạo</td><td><span class=\"en\">New staff attend two weeks of training.</span><br><span class=\"vi\">Nhân viên mới tham gia hai tuần đào tạo.</span></td></tr><tr><td><b>promotion</b></td><td>n</td><td>sự thăng chức</td><td><span class=\"en\">Tuan got a promotion after three years.</span><br><span class=\"vi\">Tuấn được thăng chức sau ba năm.</span></td></tr><tr><td><b>reference</b></td><td>n</td><td>người giới thiệu, thư giới thiệu</td><td><span class=\"en\">Please list two references from past jobs.</span><br><span class=\"vi\">Vui lòng ghi hai người giới thiệu từ các công việc trước.</span></td></tr><tr><td><b>retire</b></td><td>v</td><td>nghỉ hưu</td><td><span class=\"en\">Mr. Binh will retire at the end of this year.</span><br><span class=\"vi\">Ông Bình sẽ nghỉ hưu vào cuối năm nay.</span></td></tr></table>"}, {"h": "Cụm từ hay đi cùng", "html": "<table><tr><th>Cụm từ</th><th>Nghĩa</th></tr><tr><td>apply for a position</td><td>ứng tuyển một vị trí</td></tr><tr><td>job requirements</td><td>yêu cầu công việc</td></tr><tr><td>a qualified candidate</td><td>một ứng viên đủ năng lực</td></tr><tr><td>be promoted to manager</td><td>được thăng chức lên quản lý</td></tr><tr><td>a letter of reference</td><td>thư giới thiệu</td></tr></table>"}], "tips": ["Phân biệt người và việc: applicant / candidate (người) – application / interview (việc).", "Tin tuyển dụng thường có thứ tự: vị trí → yêu cầu → phúc lợi → cách nộp đơn."], "mistakes": ["Nói \"apply a job\" → đúng là \"apply for a job\".", "Nhầm \"benefits\" là \"lợi nhuận\" → trong tuyển dụng, benefits là phúc lợi cho nhân viên.", "Nhầm \"retire\" (nghỉ hưu) với \"resign\" (xin nghỉ việc)."], "quiz": [{"q": "Ten people ____ for the sales position last week.", "opts": ["hired", "applied", "retired", "promoted"], "a": 1, "ex": "apply for a position = ứng tuyển một vị trí. \"hired for\", \"retired for\" không hợp nghĩa với chủ ngữ là người nộp đơn."}, {"q": "\"qualified\" nghĩa là gì?", "opts": ["đã nghỉ hưu", "bán thời gian", "bắt buộc", "đủ năng lực, đủ trình độ"], "a": 3, "ex": "qualified = có đủ năng lực, bằng cấp cho một công việc."}, {"q": "The company plans to ____ five new engineers next month.", "opts": ["resign", "retire", "hire", "apply"], "a": 2, "ex": "hire + người = tuyển, thuê ai. apply / retire / resign không đi trực tiếp với tân ngữ chỉ người như vậy."}, {"q": "Trong tin tuyển dụng, \"benefits\" nghĩa là gì?", "opts": ["phúc lợi (bảo hiểm, nghỉ phép...)", "lương cơ bản", "yêu cầu công việc", "người giới thiệu"], "a": 0, "ex": "benefits = phúc lợi ngoài lương. Lương là salary, người giới thiệu là reference, yêu cầu là requirement."}, {"q": "After ten years, Mr. Hai received a ____ to manager.", "opts": ["requirement", "reference", "salary", "promotion"], "a": 3, "ex": "a promotion to manager = được thăng chức lên quản lý."}, {"q": "Please send your ____ and a cover letter to the HR department.", "opts": ["benefit", "résumé", "salary", "retirement"], "a": 1, "ex": "Khi ứng tuyển, gửi CV (résumé) kèm thư xin việc (cover letter)."}, {"q": "\"candidate\" nghĩa là gì?", "opts": ["ứng viên", "nhà tuyển dụng", "giám đốc", "nhân viên đã nghỉ"], "a": 0, "ex": "candidate = ứng viên, người đang được xem xét cho một vị trí."}, {"q": "A college degree is a ____ for this job.", "opts": ["promotion", "shift", "requirement", "candidate"], "a": 2, "ex": "a requirement for a job = một yêu cầu bắt buộc cho công việc."}]}, {"id": "tu-vung-mua-sam-giao-hang", "group": "Từ vựng", "title": "Từ vựng: Mua sắm, đặt hàng và giao hàng", "level": 1, "mins": 12, "why": "Hội thoại ở cửa hàng (Part 3), email xác nhận đơn hàng, hóa đơn và phiếu bảo hành (Part 7) đều dùng các từ này rất thường xuyên.", "sections": [{"h": "Từ vựng cốt lõi (phần 1)", "html": "<table><tr><th>Từ</th><th>Loại từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td><b>order</b></td><td>n / v</td><td>đơn hàng / đặt hàng</td><td><span class=\"en\">I ordered two chairs online.</span><br><span class=\"vi\">Mình đã đặt hai cái ghế trên mạng.</span></td></tr><tr><td><b>purchase</b></td><td>n / v</td><td>sự mua / mua</td><td><span class=\"en\">Keep the receipt for every purchase.</span><br><span class=\"vi\">Hãy giữ hóa đơn cho mỗi lần mua hàng.</span></td></tr><tr><td><b>item</b></td><td>n</td><td>món hàng</td><td><span class=\"en\">This item is not available in red.</span><br><span class=\"vi\">Món hàng này không có màu đỏ.</span></td></tr><tr><td><b>customer</b></td><td>n</td><td>khách hàng</td><td><span class=\"en\">The store gives each customer a free bag.</span><br><span class=\"vi\">Cửa hàng tặng mỗi khách một túi miễn phí.</span></td></tr><tr><td><b>receipt</b></td><td>n</td><td>hóa đơn, biên lai</td><td><span class=\"en\">You need the receipt to return this item.</span><br><span class=\"vi\">Bạn cần hóa đơn để trả lại món hàng này.</span></td></tr><tr><td><b>invoice</b></td><td>n</td><td>hóa đơn (gửi yêu cầu thanh toán)</td><td><span class=\"en\">The invoice shows a total of $250.</span><br><span class=\"vi\">Hóa đơn ghi tổng cộng 250 đô.</span></td></tr><tr><td><b>payment</b></td><td>n</td><td>sự thanh toán</td><td><span class=\"en\">We accept payment by card or cash.</span><br><span class=\"vi\">Chúng tôi nhận thanh toán bằng thẻ hoặc tiền mặt.</span></td></tr><tr><td><b>charge</b></td><td>v</td><td>tính phí, trừ tiền</td><td><span class=\"en\">They charged me $5 for delivery.</span><br><span class=\"vi\">Họ tính mình 5 đô phí giao hàng.</span></td></tr><tr><td><b>discount</b></td><td>n</td><td>sự giảm giá</td><td><span class=\"en\">Students get a 15% discount.</span><br><span class=\"vi\">Sinh viên được giảm giá 15%.</span></td></tr><tr><td><b>in stock</b></td><td>phr</td><td>còn hàng</td><td><span class=\"en\">The black model is in stock now.</span><br><span class=\"vi\">Mẫu màu đen hiện đang còn hàng.</span></td></tr></table>"}, {"h": "Từ vựng cốt lõi (phần 2)", "html": "<table><tr><th>Từ</th><th>Loại từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td><b>out of stock</b></td><td>phr</td><td>hết hàng</td><td><span class=\"en\">Sorry, this size is out of stock.</span><br><span class=\"vi\">Xin lỗi, cỡ này hết hàng rồi.</span></td></tr><tr><td><b>deliver / delivery</b></td><td>v / n</td><td>giao hàng / sự giao hàng</td><td><span class=\"en\">We deliver within two days.</span><br><span class=\"vi\">Chúng tôi giao hàng trong vòng hai ngày.</span></td></tr><tr><td><b>ship / shipment</b></td><td>v / n</td><td>gửi hàng / lô hàng</td><td><span class=\"en\">Your order will be shipped tomorrow.</span><br><span class=\"vi\">Đơn hàng của bạn sẽ được gửi đi ngày mai.</span></td></tr><tr><td><b>package</b></td><td>n</td><td>kiện hàng, gói hàng</td><td><span class=\"en\">A package arrived for you this morning.</span><br><span class=\"vi\">Sáng nay có một gói hàng gửi cho bạn.</span></td></tr><tr><td><b>track</b></td><td>v</td><td>theo dõi (đơn hàng)</td><td><span class=\"en\">You can track your order on our app.</span><br><span class=\"vi\">Bạn có thể theo dõi đơn hàng trên ứng dụng.</span></td></tr><tr><td><b>return</b></td><td>v</td><td>trả lại</td><td><span class=\"en\">You can return the shoes within 30 days.</span><br><span class=\"vi\">Bạn có thể trả lại giày trong vòng 30 ngày.</span></td></tr><tr><td><b>refund</b></td><td>n / v</td><td>tiền hoàn lại / hoàn tiền</td><td><span class=\"en\">The shop gave me a full refund.</span><br><span class=\"vi\">Cửa hàng đã hoàn lại toàn bộ tiền cho mình.</span></td></tr><tr><td><b>exchange</b></td><td>v / n</td><td>đổi (hàng)</td><td><span class=\"en\">Can I exchange this shirt for a larger size?</span><br><span class=\"vi\">Mình đổi áo này lấy cỡ lớn hơn được không?</span></td></tr><tr><td><b>warranty</b></td><td>n</td><td>bảo hành</td><td><span class=\"en\">The laptop comes with a two-year warranty.</span><br><span class=\"vi\">Máy tính có bảo hành hai năm.</span></td></tr><tr><td><b>supplier</b></td><td>n</td><td>nhà cung cấp</td><td><span class=\"en\">We buy our paper from a local supplier.</span><br><span class=\"vi\">Chúng tôi mua giấy từ một nhà cung cấp địa phương.</span></td></tr></table>"}, {"h": "Cụm từ hay đi cùng", "html": "<table><tr><th>Cụm từ</th><th>Nghĩa</th></tr><tr><td>place an order</td><td>đặt hàng</td></tr><tr><td>free shipping</td><td>miễn phí vận chuyển</td></tr><tr><td>a full refund</td><td>hoàn tiền toàn bộ</td></tr><tr><td>under warranty</td><td>còn trong thời hạn bảo hành</td></tr><tr><td>track a package</td><td>theo dõi gói hàng</td></tr></table>"}], "tips": ["Hội thoại Part 3 ở cửa hàng thường xoay quanh 3 vấn đề: hết hàng, giao trễ, hàng bị lỗi.", "Trong email xác nhận đơn hàng, hãy scan nhanh: số đơn, ngày giao, tổng tiền."], "mistakes": ["Nhầm \"refund\" (hoàn tiền) với \"exchange\" (đổi hàng khác).", "Nhầm \"receipt\" với \"recipe\" (công thức nấu ăn) vì viết gần giống nhau.", "Nghĩ \"charge\" chỉ là \"sạc pin\" → trong mua sắm, charge là tính phí, trừ tiền."], "quiz": [{"q": "The blue shirt is ____ right now, but we will get more next week.", "opts": ["on sale", "refunded", "out of stock", "in stock"], "a": 2, "ex": "\"we will get more next week\" (tuần sau có thêm) → hiện đang hết hàng: out of stock."}, {"q": "\"receipt\" nghĩa là gì?", "opts": ["hóa đơn, biên lai", "giấy bảo hành", "công thức nấu ăn", "người nhận hàng"], "a": 0, "ex": "receipt = hóa đơn, biên lai khi mua hàng. Công thức nấu ăn là recipe."}, {"q": "If the item arrives damaged, you can get a full ____.", "opts": ["supplier", "invoice", "warranty", "refund"], "a": 3, "ex": "Hàng đến bị hỏng → được hoàn tiền toàn bộ (a full refund)."}, {"q": "You can ____ your package online using this number.", "opts": ["charge", "track", "purchase", "exchange"], "a": 1, "ex": "track a package = theo dõi gói hàng bằng mã vận đơn."}, {"q": "\"warranty\" nghĩa là gì?", "opts": ["bảo hành", "hóa đơn", "giảm giá", "phí giao hàng"], "a": 0, "ex": "warranty = bảo hành, nhà sản xuất cam kết sửa chữa trong một thời gian."}, {"q": "All members get a 10% ____ on every order.", "opts": ["delivery", "receipt", "discount", "shipment"], "a": 2, "ex": "a 10% discount = giảm giá 10%."}, {"q": "We will ____ your credit card when the order is shipped.", "opts": ["track", "charge", "deliver", "return"], "a": 1, "ex": "charge a credit card = trừ tiền vào thẻ tín dụng."}, {"q": "\"supplier\" nghĩa là gì?", "opts": ["khách hàng", "người giao hàng", "thu ngân", "nhà cung cấp"], "a": 3, "ex": "supplier = nhà cung cấp hàng hóa cho công ty hoặc cửa hàng."}]}, {"id": "tu-vung-du-lich-dat-cho-su-kien", "group": "Từ vựng", "title": "Từ vựng: Du lịch, đặt chỗ và sự kiện", "level": 1, "mins": 12, "why": "Thông báo ở sân bay, khách sạn (Part 4), email đặt phòng và lịch trình hội nghị (Part 7) là những chủ đề gặp gần như ở mọi đề.", "sections": [{"h": "Từ vựng cốt lõi (phần 1)", "html": "<table><tr><th>Từ</th><th>Loại từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td><b>reservation</b></td><td>n</td><td>sự đặt chỗ</td><td><span class=\"en\">I have a reservation for two nights.</span><br><span class=\"vi\">Mình đã đặt phòng hai đêm.</span></td></tr><tr><td><b>book</b></td><td>v</td><td>đặt (vé, phòng, bàn)</td><td><span class=\"en\">We booked a table near the window.</span><br><span class=\"vi\">Chúng tôi đã đặt một bàn gần cửa sổ.</span></td></tr><tr><td><b>available</b></td><td>adj</td><td>còn trống, có sẵn</td><td><span class=\"en\">Is a room available for Friday night?</span><br><span class=\"vi\">Tối thứ Sáu còn phòng trống không?</span></td></tr><tr><td><b>cancel</b></td><td>v</td><td>hủy</td><td><span class=\"en\">She canceled her hotel booking.</span><br><span class=\"vi\">Cô ấy đã hủy đặt phòng khách sạn.</span></td></tr><tr><td><b>accommodation</b></td><td>n</td><td>chỗ ở</td><td><span class=\"en\">The price includes flights and accommodation.</span><br><span class=\"vi\">Giá đã gồm vé máy bay và chỗ ở.</span></td></tr><tr><td><b>itinerary</b></td><td>n</td><td>lịch trình chuyến đi</td><td><span class=\"en\">The tour itinerary is on page two.</span><br><span class=\"vi\">Lịch trình tour nằm ở trang hai.</span></td></tr><tr><td><b>departure</b></td><td>n</td><td>sự khởi hành</td><td><span class=\"en\">Our departure time is 6:40 A.M.</span><br><span class=\"vi\">Giờ khởi hành của chúng ta là 6:40 sáng.</span></td></tr><tr><td><b>arrival</b></td><td>n</td><td>sự đến nơi</td><td><span class=\"en\">The arrival hall is on the first floor.</span><br><span class=\"vi\">Sảnh đến ở tầng một.</span></td></tr><tr><td><b>delay</b></td><td>v / n</td><td>trì hoãn / sự chậm trễ</td><td><span class=\"en\">The train was delayed by twenty minutes.</span><br><span class=\"vi\">Tàu bị trễ hai mươi phút.</span></td></tr><tr><td><b>boarding pass</b></td><td>n</td><td>thẻ lên máy bay</td><td><span class=\"en\">Please have your boarding pass ready.</span><br><span class=\"vi\">Vui lòng chuẩn bị sẵn thẻ lên máy bay.</span></td></tr></table>"}, {"h": "Từ vựng cốt lõi (phần 2)", "html": "<table><tr><th>Từ</th><th>Loại từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td><b>luggage / baggage</b></td><td>n</td><td>hành lý</td><td><span class=\"en\">Each passenger may bring one piece of luggage.</span><br><span class=\"vi\">Mỗi hành khách được mang một kiện hành lý.</span></td></tr><tr><td><b>check in</b></td><td>v</td><td>làm thủ tục nhận phòng / lên máy bay</td><td><span class=\"en\">Guests can check in after 2 P.M.</span><br><span class=\"vi\">Khách có thể nhận phòng sau 2 giờ chiều.</span></td></tr><tr><td><b>round-trip / one-way</b></td><td>adj</td><td>khứ hồi / một chiều</td><td><span class=\"en\">A round-trip ticket is cheaper than two one-way tickets.</span><br><span class=\"vi\">Vé khứ hồi rẻ hơn hai vé một chiều.</span></td></tr><tr><td><b>fare</b></td><td>n</td><td>giá vé (xe, tàu, máy bay)</td><td><span class=\"en\">The bus fare is 7,000 dong.</span><br><span class=\"vi\">Giá vé xe buýt là 7.000 đồng.</span></td></tr><tr><td><b>conference</b></td><td>n</td><td>hội nghị</td><td><span class=\"en\">The conference will take place in Hue.</span><br><span class=\"vi\">Hội nghị sẽ diễn ra ở Huế.</span></td></tr><tr><td><b>venue</b></td><td>n</td><td>địa điểm tổ chức</td><td><span class=\"en\">The venue can hold 500 guests.</span><br><span class=\"vi\">Địa điểm này chứa được 500 khách.</span></td></tr><tr><td><b>attend</b></td><td>v</td><td>tham dự</td><td><span class=\"en\">Over 200 people attended the workshop.</span><br><span class=\"vi\">Hơn 200 người đã tham dự buổi hội thảo.</span></td></tr><tr><td><b>attendee</b></td><td>n</td><td>người tham dự</td><td><span class=\"en\">Each attendee will receive a name tag.</span><br><span class=\"vi\">Mỗi người tham dự sẽ nhận một bảng tên.</span></td></tr><tr><td><b>register / registration</b></td><td>v / n</td><td>đăng ký / sự đăng ký</td><td><span class=\"en\">Register online before May 10 to get a lower price.</span><br><span class=\"vi\">Đăng ký trực tuyến trước ngày 10/5 để được giá thấp hơn.</span></td></tr></table>"}, {"h": "Cụm từ hay đi cùng", "html": "<table><tr><th>Cụm từ</th><th>Nghĩa</th></tr><tr><td>make a reservation</td><td>đặt chỗ</td></tr><tr><td>be fully booked</td><td>đã kín chỗ</td></tr><tr><td>attend a conference</td><td>tham dự hội nghị (không có \"to\")</td></tr><tr><td>registration fee</td><td>phí đăng ký</td></tr><tr><td>a connecting flight</td><td>chuyến bay nối chuyến</td></tr></table>"}], "tips": ["Thông báo sân bay ở Part 4 hay theo mẫu: chuyến bay → vấn đề (trễ, đổi cổng) → hành khách cần làm gì.", "Trong lịch trình sự kiện, hãy scan theo giờ và tên phòng."], "mistakes": ["Nói \"attend to the meeting\" → đúng là \"attend the meeting\" (không có to).", "Nhầm \"fare\" (giá vé) với \"fee\" (phí nói chung) hay \"fair\" (hội chợ, công bằng).", "Thêm -s vào \"luggage\" / \"baggage\" → hai từ này không đếm được: \"one piece of luggage\"."], "quiz": [{"q": "I'd like to ____ a table for four at 7 P.M.", "opts": ["delay", "attend", "register", "book"], "a": 3, "ex": "book a table = đặt bàn. attend (tham dự) và register (đăng ký) không đi với \"a table\"."}, {"q": "\"venue\" nghĩa là gì?", "opts": ["lịch trình", "địa điểm tổ chức", "vé máy bay", "hành lý"], "a": 1, "ex": "venue = nơi tổ chức sự kiện như hội nghị, tiệc, buổi hòa nhạc."}, {"q": "The flight was ____ because of heavy rain, so we left two hours late.", "opts": ["delayed", "registered", "booked", "attended"], "a": 0, "ex": "\"left two hours late\" (đi trễ hai tiếng) → chuyến bay bị trễ: delayed."}, {"q": "\"itinerary\" nghĩa là gì?", "opts": ["hành lý", "giá vé", "lịch trình chuyến đi", "chỗ ở"], "a": 2, "ex": "itinerary = lịch trình chi tiết của chuyến đi."}, {"q": "More than 300 people will ____ the conference.", "opts": ["book", "attend", "check in", "depart"], "a": 1, "ex": "attend the conference = tham dự hội nghị."}, {"q": "Please show your ____ at the gate before getting on the plane.", "opts": ["registration fee", "accommodation", "venue", "boarding pass"], "a": 3, "ex": "Ở cổng ra máy bay phải trình thẻ lên máy bay (boarding pass)."}, {"q": "\"round-trip ticket\" nghĩa là gì?", "opts": ["vé miễn phí", "vé hạng thương gia", "vé khứ hồi", "vé một chiều"], "a": 2, "ex": "round-trip = khứ hồi (đi và về). Vé một chiều là one-way ticket."}, {"q": "Is this room ____ for next Saturday?", "opts": ["available", "attended", "delayed", "registered"], "a": 0, "ex": "available = còn trống. Hỏi phòng còn trống cho thứ Bảy tới không."}]}, {"id": "tu-vung-hop-lich-trinh-du-an", "group": "Từ vựng", "title": "Từ vựng: Họp, lịch trình và dự án", "level": 1, "mins": 12, "why": "Hội thoại đổi lịch họp và tiến độ dự án là chủ đề quen thuộc ở Part 3; email, memo về cuộc họp hay gặp ở Part 6–7.", "sections": [{"h": "Từ vựng cốt lõi (phần 1)", "html": "<table><tr><th>Từ</th><th>Loại từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td><b>agenda</b></td><td>n</td><td>chương trình, nội dung cuộc họp</td><td><span class=\"en\">The first item on the agenda is the budget.</span><br><span class=\"vi\">Nội dung đầu tiên của cuộc họp là ngân sách.</span></td></tr><tr><td><b>minutes</b></td><td>n</td><td>biên bản cuộc họp</td><td><span class=\"en\">Mai will take the minutes at today's meeting.</span><br><span class=\"vi\">Mai sẽ ghi biên bản cuộc họp hôm nay.</span></td></tr><tr><td><b>postpone</b></td><td>v</td><td>hoãn lại</td><td><span class=\"en\">We postponed the meeting until Thursday.</span><br><span class=\"vi\">Chúng tôi hoãn cuộc họp đến thứ Năm.</span></td></tr><tr><td><b>reschedule</b></td><td>v</td><td>sắp xếp lại lịch</td><td><span class=\"en\">Can we reschedule our call for tomorrow?</span><br><span class=\"vi\">Mình dời cuộc gọi sang ngày mai được không?</span></td></tr><tr><td><b>conference call</b></td><td>n</td><td>cuộc họp qua điện thoại</td><td><span class=\"en\">The conference call starts at 10 A.M.</span><br><span class=\"vi\">Cuộc họp qua điện thoại bắt đầu lúc 10 giờ sáng.</span></td></tr><tr><td><b>presentation</b></td><td>n</td><td>bài thuyết trình</td><td><span class=\"en\">Huy gave a short presentation on sales.</span><br><span class=\"vi\">Huy có một bài thuyết trình ngắn về doanh số.</span></td></tr><tr><td><b>proposal</b></td><td>n</td><td>bản đề xuất</td><td><span class=\"en\">The client liked our proposal.</span><br><span class=\"vi\">Khách hàng thích bản đề xuất của chúng tôi.</span></td></tr><tr><td><b>client</b></td><td>n</td><td>khách hàng (dịch vụ)</td><td><span class=\"en\">We have a meeting with a new client.</span><br><span class=\"vi\">Chúng tôi có cuộc họp với một khách hàng mới.</span></td></tr><tr><td><b>brainstorm</b></td><td>v</td><td>cùng nhau nghĩ ý tưởng</td><td><span class=\"en\">Let's brainstorm names for the new product.</span><br><span class=\"vi\">Hãy cùng nghĩ tên cho sản phẩm mới.</span></td></tr><tr><td><b>budget</b></td><td>n</td><td>ngân sách</td><td><span class=\"en\">The project is within budget.</span><br><span class=\"vi\">Dự án vẫn nằm trong ngân sách.</span></td></tr></table>"}, {"h": "Từ vựng cốt lõi (phần 2)", "html": "<table><tr><th>Từ</th><th>Loại từ</th><th>Nghĩa</th><th>Ví dụ</th></tr><tr><td><b>estimate</b></td><td>n / v</td><td>bản ước tính / ước tính</td><td><span class=\"en\">The builder sent us a cost estimate.</span><br><span class=\"vi\">Bên xây dựng gửi cho chúng tôi bản ước tính chi phí.</span></td></tr><tr><td><b>task</b></td><td>n</td><td>nhiệm vụ, công việc</td><td><span class=\"en\">Finish this task before the meeting.</span><br><span class=\"vi\">Hãy làm xong việc này trước cuộc họp.</span></td></tr><tr><td><b>assign</b></td><td>v</td><td>giao (việc)</td><td><span class=\"en\">The manager assigned the task to Trang.</span><br><span class=\"vi\">Quản lý đã giao việc đó cho Trang.</span></td></tr><tr><td><b>progress</b></td><td>n</td><td>tiến độ, sự tiến triển</td><td><span class=\"en\">Let's check the progress of the project.</span><br><span class=\"vi\">Hãy kiểm tra tiến độ dự án.</span></td></tr><tr><td><b>update</b></td><td>n / v</td><td>thông tin mới nhất / cập nhật</td><td><span class=\"en\">Please send me an update by Friday.</span><br><span class=\"vi\">Vui lòng gửi mình thông tin cập nhật trước thứ Sáu.</span></td></tr><tr><td><b>due</b></td><td>adj</td><td>đến hạn</td><td><span class=\"en\">The first draft is due on Monday.</span><br><span class=\"vi\">Bản nháp đầu tiên đến hạn vào thứ Hai.</span></td></tr><tr><td><b>behind schedule</b></td><td>phr</td><td>chậm tiến độ</td><td><span class=\"en\">The building work is behind schedule.</span><br><span class=\"vi\">Việc xây dựng đang chậm tiến độ.</span></td></tr><tr><td><b>ahead of schedule</b></td><td>phr</td><td>vượt tiến độ, sớm hơn kế hoạch</td><td><span class=\"en\">We finished two days ahead of schedule.</span><br><span class=\"vi\">Chúng tôi xong sớm hơn kế hoạch hai ngày.</span></td></tr><tr><td><b>launch</b></td><td>v / n</td><td>ra mắt / sự ra mắt</td><td><span class=\"en\">The company will launch the app in March.</span><br><span class=\"vi\">Công ty sẽ ra mắt ứng dụng vào tháng Ba.</span></td></tr><tr><td><b>complete</b></td><td>v</td><td>hoàn thành</td><td><span class=\"en\">The team completed the survey last week.</span><br><span class=\"vi\">Nhóm đã hoàn thành khảo sát tuần trước.</span></td></tr></table>"}, {"h": "Cụm từ hay đi cùng", "html": "<table><tr><th>Cụm từ</th><th>Nghĩa</th></tr><tr><td>on schedule</td><td>đúng tiến độ</td></tr><tr><td>take the minutes</td><td>ghi biên bản họp</td></tr><tr><td>give a presentation</td><td>thuyết trình</td></tr><tr><td>within / over budget</td><td>trong / vượt ngân sách</td></tr><tr><td>push back a meeting</td><td>lùi lịch họp</td></tr></table>"}], "tips": ["Part 3 hay hỏi lý do dời họp: người vắng mặt, phòng họp bận, khách đến trễ.", "postpone, reschedule, push back, put off đều có thể là paraphrase của nhau: \"dời lịch\"."], "mistakes": ["Hiểu \"minutes\" chỉ là \"phút\" → trong cuộc họp, minutes là biên bản.", "Viết \"assign a task for someone\" → đúng là \"assign a task to someone\" hoặc \"assign someone a task\".", "Nhầm \"behind schedule\" (chậm tiến độ) với \"ahead of schedule\" (sớm hơn kế hoạch)."], "quiz": [{"q": "The meeting has been ____ until next Tuesday because the manager is sick.", "opts": ["postponed", "estimated", "launched", "assigned"], "a": 0, "ex": "Quản lý bị ốm nên cuộc họp bị hoãn đến thứ Ba: postponed."}, {"q": "\"agenda\" nghĩa là gì?", "opts": ["biên bản cuộc họp", "ngân sách", "chương trình, nội dung cuộc họp", "khách hàng"], "a": 2, "ex": "agenda = danh sách nội dung sẽ bàn trong cuộc họp. Biên bản là minutes."}, {"q": "Trong cuộc họp, \"minutes\" nghĩa là gì?", "opts": ["bài thuyết trình", "biên bản cuộc họp", "lịch làm việc", "số phút"], "a": 1, "ex": "take the minutes = ghi biên bản. Trong ngữ cảnh họp, minutes không có nghĩa là phút."}, {"q": "The project is ____ schedule, so we need to work faster.", "opts": ["ahead of", "within", "due", "behind"], "a": 3, "ex": "\"need to work faster\" (cần làm nhanh hơn) → đang chậm tiến độ: behind schedule."}, {"q": "We will ____ the new product in March.", "opts": ["assign", "brainstorm", "launch", "complete"], "a": 2, "ex": "launch a product = ra mắt sản phẩm."}, {"q": "The report is ____ on Friday, so please don't be late.", "opts": ["due", "estimate", "behind", "ahead"], "a": 0, "ex": "be due on + ngày = đến hạn vào ngày đó."}, {"q": "\"budget\" nghĩa là gì?", "opts": ["tiến độ", "nhiệm vụ", "bản đề xuất", "ngân sách"], "a": 3, "ex": "budget = ngân sách. Tiến độ là progress, đề xuất là proposal, nhiệm vụ là task."}, {"q": "The manager ____ each task to a different team member.", "opts": ["launched", "assigned", "estimated", "postponed"], "a": 1, "ex": "assign something to someone = giao việc gì cho ai."}]}];
